import {announce,createFocusTrap,startMeasure,installGlobalShortcuts,withBusy} from './lib/ux.js';
import {createCommandPalette} from './lib/commands.js';
import {governanceModel,renderStage4Governance,bindStage4Governance} from './features/decisions/stage4Governance.js';
import {renderDecisionLineage} from './components/DecisionLineage.js';
import {renderOpportunitySolutionTree} from './components/OpportunitySolutionTree.js';
import {recordUXMetric,webVitals} from './lib/telemetry.js';

const KEY='thinkforge_prod_v7', EVENTS='thinkforge_events_v7';
async function authHeaders(){const h={'Content-Type':'application/json'};try{const sess=(await supa?.auth.getSession())?.data?.session;if(sess?.access_token)h.Authorization='Bearer '+sess.access_token}catch{}return h}
function apiUrl(path){const base=(state?.settings?.djangoApiBase||'').replace(/\/$/,'');return base?base+path:path}
async function apiPost(url,body){const h=await authHeaders();return fetch(apiUrl(url),{method:'POST',headers:h,body:JSON.stringify(body)})}
const DEFAULT={version:3,user:null,decisions:[{id:'d1',title:'Recover failed checkouts',problem:'Should we add a safer payment recovery flow after a failed payment?',user:'Customers on mobile checkout',context:'Payment failure is a visible drop-off point and users may fear duplicate charges.',status:'build',createdAt:'2026-08-20',updatedAt:'2026-09-03',assumptions:[{id:'a1',text:'Payment failure is a material driver of checkout abandonment.',impact:5,uncertainty:3,confidence:.72,status:'validated',rationale:'Behavioral analytics indicates payment failure occurs near the major checkout drop.'},{id:'a2',text:'A clearer recovery flow will recover a meaningful share of failed checkouts.',impact:5,uncertainty:4,confidence:.42,status:'open',rationale:'Plausible, but direct experiment evidence is missing.'},{id:'a3',text:'Customers will not interpret retry options as duplicate-charge risk.',impact:5,uncertainty:5,confidence:.28,status:'open',rationale:'Safety perception is not yet validated.'}],evidence:[{id:'e1',type:'analytics',source:'Checkout analytics',content:'Payment failures account for 13% of mobile checkout exits in the last 30 days.',stance:'supports',strength:'strong',date:'2026-08-28',linked:['a1'],url:''},{id:'e2',type:'interview',source:'Customer interview #7',content:'I was worried I would be charged twice so I left after the first attempt.',stance:'supports',strength:'medium',date:'2026-08-30',linked:['a3'],url:''}],challenges:[{id:'c1',priority:1,assumption:'A clearer recovery flow will recover a meaningful share of failed checkouts.',question:'What evidence shows that recovery friction—not payment method failure itself—is the main driver?',why:'If the root cause is processor failure, a UX change could have limited impact.',evidence_refs:['e1']}],alternatives:[{name:'Build full recovery flow',impact:8,effort:7,risk:6,evidence:5,reversibility:5},{name:'Concierge/manual recovery pilot',impact:5,effort:3,risk:3,evidence:8,reversibility:9},{name:'Do nothing',impact:1,effort:1,risk:8,evidence:5,reversibility:10}],experiment:{hypothesis:'A clearer recovery screen with safe retry guidance will increase recovery of failed checkouts.',control:'Current failure state',intervention:'Recovery screen with retry + alternate method + duplicate-charge reassurance',primary:'Payment recovery rate',guardrails:['Duplicate-payment complaints','Support tickets'],baseline:'0%',target:'+10% relative',prediction:'+12%',successRule:'Recovery improves by at least 10% relative without guardrail regression.',failureRule:'Recovery improves <5% or duplicate-payment complaints increase materially.',status:'planned'},prediction:{metric:'Payment recovery rate',predicted:12,confidence:70},outcome:{actual:4.8,notes:'Pilot improved recovery modestly but missed the success threshold.',result:'partial_success'},learning:'Users valued reassurance, but payment-method availability remained a stronger constraint.',prd:'',jira:[]},{id:'d2',title:'AI interview prep',problem:'Should we add personalized interview practice for early-career users?',user:'Early-career job seekers',context:'Users want feedback but may not trust AI coaching.',status:'validate',createdAt:'2026-08-25',updatedAt:'2026-09-02',assumptions:[{id:'a4',text:'Users trust AI feedback enough to repeat sessions.',impact:5,uncertainty:5,confidence:.25,status:'open',rationale:'No behavioral evidence yet.'},{id:'a5',text:'Personalization materially improves repeat usage.',impact:4,uncertainty:4,confidence:.32,status:'open',rationale:'Existing generic feedback is easier to compare than personalized impact.'}],evidence:[{id:'e3',type:'interview',source:'Research note',content:'Several users said feedback is useful when it feels specific to their answer.',stance:'supports',strength:'medium',date:'2026-08-29',linked:['a5'],url:''}],challenges:[],alternatives:[],experiment:{hypothesis:'Personalized feedback increases repeat practice sessions.',control:'Generic feedback',intervention:'Personalized feedback by role',primary:'D7 repeat session rate',guardrails:['Session abandonment'],baseline:'18%',target:'22%',prediction:'+20%',successRule:'D7 improves by >=15% relative.',failureRule:'D7 improves <5%.',status:'draft'},prediction:{metric:'D7 repeat session rate',predicted:20,confidence:50},outcome:{actual:null,notes:'',result:'pending'},learning:'',prd:'',jira:[]}],research:{hypotheses:[{id:'h1',text:'Structured AI challenge produces better-supported product decisions than direct recommendation.',status:'untested'},{id:'h2',text:'Users prefer concise, high-impact questions over long AI critiques.',status:'untested'}],interviews:[{id:'i1',title:'APM interview #01',audience:'APM',notes:'Current decisions live across docs, chats and spreadsheets; reasoning gaps are rarely logged.',date:'2026-08-31'}],findings:[{id:'f1',text:'Users want evidence and uncertainty to stay linked to the decision, not buried in separate documents.',source:'Synthesis',confidence:'medium'}]},rag:{documents:[],chunks:[]},evals:[],events:[],settings:{supabaseUrl:'',supabaseAnonKey:'',posthogKey:'',posthogHost:'https://us.i.posthog.com'}};
let state=load(); state.settings={...(state.settings||{}),offlineDemo:state.settings?.offlineDemo!==false}; let view='dashboard', decisionId=state.decisions[0]?.id||null, tab='overview', supa=null; let aiState={status:'idle',label:'',action:null}; let lastSnapshot=null; let undoing=false; let modalCleanup=()=>{};
const $=s=>document.querySelector(s); const esc=s=>String(s??'').replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[m]));
function load(){try{const x=JSON.parse(localStorage.getItem(KEY));if(x?.version===3){x.research=x.research||{};x.research.version=x.research.version||2;return x}return structuredClone(DEFAULT)}catch{return structuredClone(DEFAULT)}}
function localSave(){localStorage.setItem(KEY,JSON.stringify(state))}
let save=localSave
function commit(message='Saved'){if(!undoing)lastSnapshot=structuredClone(state);save();announce(message);toast(message)}
function undoLast(){if(!lastSnapshot){toast('Nothing to undo');announce('Nothing to undo');return}const now=structuredClone(state);undoing=true;state=lastSnapshot;lastSnapshot=now;save();undoing=false;announce('Last change undone');toast('Undone');render()}
function toast(t,undo=false){const e=$('#toast');if(!e)return;e.innerHTML=undo?`${esc(t)} <button class="toast-undo" id="toastUndo">Undo</button>`:esc(t);e.classList.add('show');if(undo)e.querySelector('#toastUndo')?.addEventListener('click',undoLast,{once:true});clearTimeout(window.__toastTimer);window.__toastTimer=setTimeout(()=>e.classList.remove('show'),2400)}
async function track(name,props={}){const ev={name,ts:new Date().toISOString(),props};state.events.push(ev);if(state.events.length>1000)state.events=state.events.slice(-1000);localSave();syncCloud();if(state.settings.posthogKey){try{await fetch((state.settings.posthogHost||'https://us.i.posthog.com').replace(/\/$/,'')+'/capture/',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({api_key:state.settings.posthogKey,event:name,distinct_id:state.user?.id||('anon-'+location.host),properties:props||{}})})}catch{}}}
function current(){return state.decisions.find(d=>d.id===decisionId)||state.decisions[0]}
function openModal(html){modalCleanup();$('#modal').innerHTML=html;$('#modalWrap').classList.add('open');modalCleanup=createFocusTrap($('#modal'),{onClose:closeModal});setTimeout(()=>$('#modal button, #modal input, #modal textarea, #modal select')?.focus(),0);announce('Dialog opened')} function closeModal(){modalCleanup();modalCleanup=()=>{};$('#modalWrap').classList.remove('open');announce('Dialog closed')}
$('#modalWrap').addEventListener('click',e=>{if(e.target.id==='modalWrap')closeModal()});

document.querySelectorAll('[data-view]').forEach(b=>b.addEventListener('click',()=>{view=b.dataset.view;tab=view==='decisions'?'overview':tab;render()}));
$('#resetBtn').onclick=()=>{if(confirm('Reset the local demo data?')){state=structuredClone(DEFAULT);save();decisionId=state.decisions[0].id;view='dashboard';render();toast('Demo reset')}};
$('#settingsBtn').onclick=showSettings; $('#authBtn').onclick=showAuth;
function stageStatus(){return `<div class="banner success"><strong>${state.settings.offlineDemo?'Free Offline Demo':'15-stage ThinkForge'}:</strong> ${state.settings.offlineDemo?'No API keys, login, database, or paid providers are required. Results marked deterministic-demo are examples, not live AI or user research.':'Discovery, decision workflow, AI evaluation, analytics, RAG, execution, and advanced insights are enabled.'}</div>`}
function render(){recordUXMetric(state,'view_rendered',{view});document.querySelectorAll('[data-view]').forEach(b=>b.classList.toggle('active',b.dataset.view===view));const map={dashboard:renderDash,decisions:renderDecisions,discovery:renderDiscovery,evidence:renderEvidence,experiments:renderExperiments,insights:renderInsights,evaluation:renderEvaluation,analytics:renderAnalytics,agent:renderAgent,rag:renderRag,execution:renderExecution};($('#root')).innerHTML=(map[view]||renderDash)();bind();}
function top(ey,ttl,sub,actions=''){const aiBanner=aiState.status!=='idle'?`<div class="ai-state ${aiState.status}" role="status" aria-live="polite"><span class="ai-state-dot"></span><span>${esc(aiState.label)}</span>${aiState.status==='error'?'<button class="btn ghost" id="aiRetry">Retry</button>':''}</div>`:'';return `<div class="top"><div><div class="eyebrow">${ey}</div><h1>${ttl}</h1><div class="sub">${sub}</div></div><div class="actions">${actions}</div></div>${aiBanner}`}
function renderDash(){const ds=state.decisions||[];const attention=ds.map(d=>({d,a:(d.assumptions||[]).filter(x=>x.status!=='validated').sort((x,y)=>(y.impact*y.uncertainty)-(x.impact*x.uncertainty))[0]})).sort((x,y)=>((y.a?.impact||0)*(y.a?.uncertainty||0))-((x.a?.impact||0)*(x.a?.uncertainty||0)));const primary=attention[0]?.d||ds[0];const next=primary?nextAction(primary):'Create a decision to start the loop.';return top('Home','Make the decision, not the dashboard.','Keep the important question, uncertainty, evidence, and next action in one place.',`<button class="btn primary" id="newDecision">New decision</button>`)+`<div class="home-hero card pad"><div><div class="section-kicker">Focus today</div><h2 style="font-size:22px;margin:5px 0 3px">${primary?esc(primary.title):'Start your first decision'}</h2><div class="sub">${primary?esc(primary.problem||primary.context||'Define the decision you need to make.'):'Capture a decision, then bring evidence and uncertainty into view.'}</div></div><div class="home-hero-side"><div class="status-line"><span class="status-dot ${primary?'live':''}"></span>${primary?'Needs attention':'Ready to start'}</div><button class="btn" data-open-decision="${primary?.id||''}" ${primary?'':'disabled'}>Open workspace</button></div></div><div class="section"><div class="section-head"><h2>Decisions needing attention</h2><button class="btn ghost" id="openDecisions">View all</button></div><div class="list">${attention.slice(0,5).map(({d,a})=>`<div class="decision-card" data-open-decision="${d.id}"><div class="item-head"><div><div class="section-kicker">${esc(d.status||'validate')}</div><div class="decision-title">${esc(d.title)}</div><div class="decision-summary">${esc(d.problem||d.context||'No decision statement yet.')}</div></div><span class="pill ${a?.status==='open'?'warn':'good'}">${a?'Uncertain':'Ready'}</span></div><div class="decision-meta"><span>${(d.evidence||[]).length} evidence</span><span>${(d.assumptions||[]).filter(x=>x.status!=='validated').length} open assumptions</span><span>${d.outcome?.actual!==null&&d.outcome?.actual!==undefined?'Outcome recorded':'Outcome pending'}</span></div></div>`).join('')||'<div class="empty">No decisions yet. Create the first one.</div>'}</div></div><div class="section focus-grid"><div class="card pad"><div class="section-kicker">Next best action</div><h2 style="font-size:19px;margin:5px 0 8px">${esc(next)}</h2><div class="note">ThinkForge prioritizes the highest-impact unresolved uncertainty rather than another dashboard metric.</div></div><div class="card pad"><div class="section-kicker">Decision signal</div><div class="insight-line"><strong>${ds.length}</strong><span>active decisions</span></div><div class="insight-line"><strong>${ds.reduce((n,d)=>n+(d.evidence?.length||0),0)}</strong><span>evidence items</span></div><div class="insight-line"><strong>${ds.filter(d=>d.outcome?.actual!==null&&d.outcome?.actual!==undefined).length}</strong><span>outcomes recorded</span></div></div></div>`}

function decisionCard(d){const open=(d.assumptions||[]).filter(a=>a.status==='open').length;return `<div class="card pad" data-open-decision="${d.id}" style="cursor:pointer"><div class="item-head"><span class="pill ${d.status==='build'?'good':d.status==='do_not_build'?'bad':'warn'}">${esc(d.status)}</span><span class="note">${esc(d.updatedAt||'')}</span></div><div style="font-weight:900;font-size:16px;margin-top:12px">${esc(d.title)}</div><div class="note" style="margin-top:5px">${esc(d.problem)}</div><div class="meta" style="margin-top:12px"><span class="pill">${open} open assumptions</span><span class="pill">${d.evidence?.length||0} evidence</span></div></div>`}
function stage4Readiness(d){const g=governanceModel(d);const r=g.rigor==='quick'||g.rigor==='minimal'?1:g.rigor==='high_stakes'||g.rigor==='maximum'?4:g.rigor==='significant'||g.rigor==='high'?3:2;const blockers=[];if(!String(d.title||'').trim()||!String(d.problem||'').trim())blockers.push({code:'MISSING_DECISION_CONTEXT',label:'Define the decision question and problem'});if(g.evidenceCount<r)blockers.push({code:'INSUFFICIENT_EVIDENCE',label:`Add at least ${r} evidence item${r===1?'':'s'}`});if(g.evidenceQuality<({quick:.55,standard:.65,significant:.75,high_stakes:.85}[g.rigor]||.65))blockers.push({code:'LOW_EVIDENCE_QUALITY',label:`Evidence quality is ${Math.round(g.evidenceQuality*100)}%`});if(g.criticalOpen&&g.rigor!=='quick')blockers.push({code:'CRITICAL_ASSUMPTIONS_OPEN',label:`Resolve ${g.criticalOpen} critical assumption${g.criticalOpen===1?'':'s'}`});if(g.contradictions.some(c=>['high','critical'].includes(String(c.severity||'').toLowerCase()))&&g.rigor!=='quick')blockers.push({code:'HIGH_CONTRADICTION',label:'Resolve high-severity contradiction'});if(g.alternatives<({quick:1,standard:2,significant:2,high_stakes:3}[g.rigor]||2))blockers.push({code:'INSUFFICIENT_OPTIONS',label:'Add and compare credible options'});return {required:g.rigor,minEv:r,evidenceCount:g.evidenceCount,criticalOpen:g.criticalOpen,contradictions:g.contradictions.length,blockers,readyForReview:!blockers.length,hasExp:!!d.experiment?.hypothesis&&!!d.experiment?.primary,hasPred:!!d.prediction,hasOutcome:d.outcome?.actual!==null&&d.outcome?.actual!==undefined,hasLearning:!!d.learning,confidence:g.confidence,workflowState:g.workflowState,next:g.next}}
function stage4Transition(to){const d=current(),r=stage4Readiness(d),from=d.workflowState||'DRAFT',allowed={DRAFT:['INVESTIGATING','ARCHIVED'],INVESTIGATING:['READY_FOR_REVIEW','DRAFT','ARCHIVED'],READY_FOR_REVIEW:['APPROVED','INVESTIGATING','ARCHIVED'],APPROVED:['EXECUTING','INVESTIGATING','ARCHIVED'],EXECUTING:['OBSERVING','INVESTIGATING'],OBSERVING:['LEARNED','INVESTIGATING'],LEARNED:['ARCHIVED','INVESTIGATING'],ARCHIVED:[]};if(!(allowed[from]||[]).includes(to))return toast(`Cannot move from ${from.replaceAll('_',' ')} to ${to.replaceAll('_',' ')}`);if(to==='READY_FOR_REVIEW'&&!r.readyForReview)return toast(`Blocked: ${r.blockers[0]?.label||'readiness gates are open'}`);if(to==='LEARNED'&&!(r.hasOutcome&&r.hasLearning))return toast('Outcome and learning are required');const now=new Date().toISOString();d.workflowHistory=d.workflowHistory||[];d.workflowHistory.push({from,to,at:now,reason:r.next});d.workflowState=to;d.workflowStateVersion=(d.workflowStateVersion||1)+1;if(to==='APPROVED')d.approvedAt=now;commit(`Decision moved to ${to.replaceAll('_',' ')}`);track('decision_workflow_transition',{decision_id:d.id,from,to,state_version:d.workflowStateVersion});render()}
function renderDecisions(){const d=current();if(!d)return top('Decisions','No decisions yet','Create your first product decision.',`<button class="btn primary" id="newDecision">New decision</button>`);const r=stage4Readiness(d),stages=[['overview','Context'],['governance','Governance'],['evidence','Evidence'],['assumptions','Assumptions'],['challenge','Challenges'],['alternatives','Options'],['experiment','Experiment'],['outcome','Outcome']],flow=['DRAFT','INVESTIGATING','READY_FOR_REVIEW','APPROVED','EXECUTING','OBSERVING','LEARNED'];return top('Decision','Decision workspace','One governed decision context, one evidence trail, one accountable next action.',`<button class="btn" id="newDecision">New</button><button class="btn" id="snapshotDecision">Capture snapshot</button>`)+`<div class="decision-context"><strong>${esc(d.title)}</strong><span>·</span><span>${esc(d.user||'Target user not defined')}</span><span>·</span><span>${esc(d.updatedAt||'Updated recently')}</span><span class="pill ${r.readyForReview?'good':'warn'}">${esc(r.workflowState.replaceAll('_',' '))}</span></div><div class="card" style="margin-top:14px"><div class="hero"><div class="item-head"><div><div class="section-kicker">Decision D-${esc(String(d.id).replace(/\D/g,''))}</div><h2 style="margin:5px 0 4px;font-size:24px">${esc(d.title)}</h2><div class="sub">${esc(d.problem||'Define the decision statement.')}</div></div><div class="right"><div class="score"><div class="big">${Math.round(r.confidence*100)}%</div></div><div class="note">explainable confidence</div></div></div></div><div class="decision-workflow">${flow.map((x,i)=>`<div class="workflow-step ${r.workflowState===x?'current':''} ${flow.indexOf(r.workflowState)>i?'complete':''}"><span>${i+1}</span><small>${x.replaceAll('_',' ')}</small></div>`).join('')}</div><div class="governance-strip"><div><strong>${r.readyForReview?'Ready for review':'Not ready for review'}</strong><div class="note">${r.blockers.length?esc(r.blockers[0].label):'All current review gates are satisfied.'}</div></div><div class="actions">${r.workflowState==='DRAFT'?'<button class="btn primary" id="startInvestigation">Start investigation</button>':''}${r.workflowState==='INVESTIGATING'?'<button class="btn primary" id="submitReview">Submit for review</button>':''}${r.workflowState==='READY_FOR_REVIEW'?'<button class="btn primary" id="approveDecision">Approve decision</button>':''}${r.workflowState==='APPROVED'?'<button class="btn primary" id="executeDecision">Start execution</button>':''}${r.workflowState==='EXECUTING'?'<button class="btn primary" id="observeDecision">Start observation</button>':''}${r.workflowState==='OBSERVING'&&r.hasOutcome&&r.hasLearning?'<button class="btn primary" id="learnDecision">Mark learned</button>':''}</div></div><div class="pad"><div class="focus-grid"><div>${renderDecisionTab(d)}</div><aside class="focus-panel"><div class="section-kicker">Decision signal</div><div class="next-action" style="margin-top:8px"><strong>Next best action</strong><span>${esc(r.next)}</span></div><div class="section"><div class="section-kicker">Confidence composition</div><div class="confidence-grid"><div><strong>${Math.round(r.confidence*100)}%</strong><span class="note">overall</span></div><div><strong>${Math.round((r.evidenceCount?Math.min(1,r.evidenceCount/r.minEv):0)*100)}%</strong><span class="note">evidence gate</span></div><div><strong>${r.criticalOpen===0?'Clear':'Open'}</strong><span class="note">critical assumptions</span></div></div></div><div class="section"><div class="section-kicker">Readiness gates</div>${r.blockers.length?r.blockers.slice(0,4).map(b=>`<div class="gate-row blocked"><span>!</span><span>${esc(b.label)}</span></div>`).join(''):'<div class="gate-row clear"><span>✓</span><span>No open review blockers.</span></div>'}</div><div class="section"><div class="section-kicker">Recent decision history</div>${(d.workflowHistory||[]).slice(-3).reverse().map(h=>`<div class="history-row"><strong>${esc(h.to.replaceAll('_',' '))}</strong><span>${esc(new Date(h.at).toLocaleString())}</span></div>`).join('')||'<div class="note">No transitions recorded yet.</div>'}</div></aside></div></div></div>`}

function renderDecisionTab(d){if(tab==='governance')return renderStage4Governance(d,esc);if(tab==='overview')return `<div class="grid g2"><div class="form"><div class="field"><label>Decision</label><input id="dTitle" value="${esc(d.title)}"></div><div class="field"><label>Problem</label><textarea id="dProblem">${esc(d.problem)}</textarea></div><div class="field"><label>Target user</label><input id="dUser" value="${esc(d.user||'')}"></div><div class="field"><label>Context</label><textarea id="dContext">${esc(d.context||'')}</textarea></div></div><div><div class="banner ${d.status==='build'?'success':'warn'}"><strong>Current recommendation:</strong> ${esc(d.status)}</div><div class="mini"><div class="status">Evidence strength</div><div class="score"><div class="big">${evidenceScore(d)}%</div></div><div class="note">Weighted from evidence strength and linked critical assumptions.</div></div><div class="section"><div class="section-head"><h2>Next best action</h2></div><div class="callout">${nextAction(d)}</div></div></div></div>`;
if(tab==='assumptions')return `<div class="section-head"><h2>Critical assumptions</h2><div class="actions"><button class="btn" id="genAssumptions">AI map assumptions</button><button class="btn primary" id="addAssumption">+ Add</button></div></div><div class="list">${(d.assumptions||[]).map((a,i)=>`<div class="item"><div class="item-head"><div><strong>${esc(a.text)}</strong><div class="note">${esc(a.rationale||'')}</div></div><span class="pill ${a.status==='validated'?'good':'warn'}">${esc(a.status)}</span></div><div class="grid g3" style="margin-top:10px"><div class="mini"><div class="note">Impact</div><strong>${a.impact}/5</strong></div><div class="mini"><div class="note">Uncertainty</div><strong>${a.uncertainty}/5</strong></div><div class="mini"><div class="note">Priority</div><strong>${a.impact*a.uncertainty}/25</strong></div></div><div style="margin-top:10px;display:flex;gap:7px;justify-content:flex-end"><button class="btn ghost" data-toggle-assumption="${a.id}">${a.status==='validated'?'Re-open':'Validate'}</button><button class="btn ghost" data-edit-assumption="${a.id}">Edit</button></div></div>`).join('')}</div>`;
if(tab==='evidence')return `<div class="section-head"><div><div class="section-kicker">Traceable inputs</div><h2 style="margin:4px 0 0">Evidence</h2></div><div class="actions"><button class="btn" id="openRagFromDecision">Retrieve from RAG</button><button class="btn primary" id="addEvidence">Add evidence</button></div></div><div>${(d.evidence||[]).map((e,i)=>`<div class="evidence-row" data-inspect-evidence="${e.id}"><div class="evidence-index">E${i+1}</div><div><div class="evidence-source">${esc(e.source)}</div><div class="note">${esc(e.type)} · ${esc(e.date||'')} · ${esc(e.strength||'medium')}</div><div class="evidence-text">${esc(e.content)}</div><div class="meta"><span class="pill ${e.stance==='supports'?'good':e.stance==='contradicts'?'bad':''}">${esc(e.stance||'neutral')}</span><span class="note">${(e.linked||[]).length} linked assumptions</span></div></div><span class="btn ghost" style="padding:4px 0">Inspect</span></div>`).join('')||'<div class="empty">No evidence yet. Add a source or retrieve one from RAG.</div>'}</div>`;
if(tab==='challenge')return `<div class="section-head"><h2>AI challenge queue</h2><button class="btn primary" id="genChallenges">Generate challenges</button></div><div class="list">${(d.challenges||[]).map(c=>`<div class="item"><div class="item-head"><strong>#${c.priority||1} ${esc(c.question)}</strong><span class="pill warn">High leverage</span></div><div style="margin-top:7px"><strong>Assumption:</strong> ${esc(c.assumption)}</div><div class="note" style="margin-top:5px">${esc(c.why)}</div><div class="meta">${(c.evidence_refs||[]).map(x=>`<span class="pill">${esc(x)}</span>`).join('')}</div></div>`).join('')||'<div class="empty">No challenges yet. Generate them from the highest-impact uncertainties.</div>'}</div>`;
if(tab==='alternatives')return `<div class="section-head"><h2>Alternatives & tradeoffs</h2><button class="btn primary" id="addAlternative">+ Add option</button></div><table class="table"><thead><tr><th>Option</th><th>Impact</th><th>Effort</th><th>Risk</th><th>Evidence</th><th>Reversibility</th></tr></thead><tbody>${(d.alternatives||[]).map(o=>`<tr><td><strong>${esc(o.name)}</strong></td><td>${o.impact}</td><td>${o.effort}</td><td>${o.risk}</td><td>${o.evidence}</td><td>${o.reversibility}</td></tr>`).join('')}</tbody></table>`;
if(tab==='experiment')return `<div class="grid g2"><div class="form"><div class="field"><label>Hypothesis</label><textarea id="exHyp">${esc(d.experiment?.hypothesis||'')}</textarea></div><div class="field"><label>Control</label><input id="exCtl" value="${esc(d.experiment?.control||'')}"></div><div class="field"><label>Intervention</label><input id="exInt" value="${esc(d.experiment?.intervention||'')}"></div><div class="field"><label>Primary metric</label><input id="exPrimary" value="${esc(d.experiment?.primary||'')}"></div><div class="field"><label>Guardrails (comma-separated)</label><input id="exGuard" value="${esc((d.experiment?.guardrails||[]).join(', '))}"></div></div><div class="form"><div class="field"><label>Prediction</label><input id="exPred" value="${esc((d.prediction?.predicted ?? d.experiment?.prediction ?? ''))}"></div><div class="field"><label>Success rule</label><textarea id="exSuccess">${esc(d.experiment?.successRule||'')}</textarea></div><div class="field"><label>Failure rule</label><textarea id="exFail">${esc(d.experiment?.failureRule||'')}</textarea></div><div class="actions"><button class="btn" id="genExperiment">AI design experiment</button><button class="btn primary" id="saveExperiment">Save experiment</button></div></div></div>`;
return `<div class="grid g2"><div class="card pad"><div class="score"><div class="big">${d.outcome?.actual===null?'—':esc(d.outcome.actual)}</div><div class="note">actual result</div></div><div class="note">Prediction: ${esc(d.prediction?.predicted??'—')}</div><div class="bar" style="margin-top:10px"><span style="width:${calibrationBar(d)}%"></span></div></div><div><div class="field"><label>Actual outcome</label><input id="outActual" value="${d.outcome?.actual??''}" placeholder="e.g. 4.8"></div><div class="field" style="margin-top:10px"><label>Result</label><select id="outResult"><option value="pending" ${d.outcome?.result==='pending'?'selected':''}>Pending</option><option value="success" ${d.outcome?.result==='success'?'selected':''}>Success</option><option value="partial_success" ${d.outcome?.result==='partial_success'?'selected':''}>Partial success</option><option value="failure" ${d.outcome?.result==='failure'?'selected':''}>Failure</option></select></div><div class="field" style="margin-top:10px"><label>Learning</label><textarea id="outLearning">${esc(d.learning||'')}</textarea></div><button class="btn primary" style="margin-top:10px" id="saveOutcome">Record outcome</button></div></div>`}
function decisionConfidence(d){const as=d.assumptions||[];if(!as.length)return .35;return as.reduce((s,a)=>s+(a.confidence??.4)*(a.status==='validated'?1:.7),0)/as.length}
function evidenceScore(d){const m={strong:1,medium:.65,weak:.35};if(!d.evidence?.length)return 0;return Math.round(d.evidence.reduce((s,e)=>s+(m[e.strength]||.5),0)/d.evidence.length*100)}
function calibrationBar(d){const p=Number(d.prediction?.predicted),a=Number(d.outcome?.actual);if(!Number.isFinite(p)||!Number.isFinite(a)||p===0)return 0;return Math.max(0,Math.min(100,100-Math.abs(p-a)/Math.abs(p)*100))}
function nextAction(d){const open=(d.assumptions||[]).filter(a=>a.status!=='validated').sort((a,b)=>(b.impact*b.uncertainty)-(a.impact*a.uncertainty))[0];if(open)return `Investigate: <strong>${esc(open.text)}</strong>. Attach evidence or run a small experiment.`;if(d.experiment?.status==='planned'&&d.outcome?.actual===null)return 'Run the planned experiment and record your prediction before observing results.';if(d.outcome?.actual!==null&&!d.learning)return 'Record the learning and update the assumption that drove the decision.';return 'Decision is sufficiently supported for the current stage.'}
function bind(){document.querySelector('#startInvestigation')?.addEventListener('click',()=>stage4Transition('INVESTIGATING'));document.querySelector('#submitReview')?.addEventListener('click',()=>stage4Transition('READY_FOR_REVIEW'));document.querySelector('#approveDecision')?.addEventListener('click',()=>stage4Transition('APPROVED'));document.querySelector('#executeDecision')?.addEventListener('click',()=>stage4Transition('EXECUTING'));document.querySelector('#observeDecision')?.addEventListener('click',()=>stage4Transition('OBSERVING'));document.querySelector('#learnDecision')?.addEventListener('click',()=>stage4Transition('LEARNED'));document.querySelector('#snapshotDecision')?.addEventListener('click',()=>{const d=current();d.localSnapshots=d.localSnapshots||[];d.localSnapshots.push({version:d.workflowStateVersion||1,workflowState:d.workflowState||'DRAFT',capturedAt:new Date().toISOString(),decision:structuredClone(d)});commit('Decision snapshot captured');track('decision_snapshot_captured',{decision_id:d.id,version:d.workflowStateVersion||1});render()});document.querySelectorAll('[data-open-decision]').forEach(e=>e.onclick=()=>{if(!e.dataset.openDecision)return;decisionId=e.dataset.openDecision;view='decisions';tab='overview';track('decision_opened',{decision_id:decisionId});render()});$('#newDecision')?.addEventListener('click',newDecision);$('#openDecisions')?.addEventListener('click',()=>{view='decisions';render()});document.querySelectorAll('[data-tab]').forEach(e=>e.onclick=()=>{tab=e.dataset.tab;render()});$('#saveDecision')?.addEventListener('click',()=>{const d=current();d.title=$('#dTitle')?.value?.trim()||d.title;d.problem=$('#dProblem')?.value?.trim()||d.problem;d.user=$('#dUser')?.value?.trim()||'';d.context=$('#dContext')?.value?.trim()||'';d.updatedAt=new Date().toISOString().slice(0,10);commit('Decision saved');track('decision_saved',{decision_id:d.id});render()});$('#genAssumptions')?.addEventListener('click',()=>ai('assumptions'));$('#genChallenges')?.addEventListener('click',()=>ai('challenge'));$('#genExperiment')?.addEventListener('click',()=>ai('experiment'));$('#openRagFromDecision')?.addEventListener('click',()=>{view='rag';render()});$('#addEvidence')?.addEventListener('click',addEvidence);$('#addAssumption')?.addEventListener('click',addAssumption);$('#addAlternative')?.addEventListener('click',addAlternative);$('#saveExperiment')?.addEventListener('click',saveExperiment);$('#saveOutcome')?.addEventListener('click',saveOutcome);document.querySelectorAll('[data-toggle-assumption]').forEach(b=>b.onclick=()=>{const a=current().assumptions.find(x=>x.id===b.dataset.toggleAssumption);a.status=a.status==='validated'?'open':'validated';commit('Assumption status updated');track('assumption_status_changed',{assumption_id:a.id});render()});document.querySelectorAll('[data-edit-assumption]').forEach(b=>b.onclick=()=>editAssumption(b.dataset.editAssumption));document.querySelectorAll('[data-inspect-evidence]').forEach(e=>e.onclick=()=>{const d=current(),ev=(d.evidence||[]).find(x=>x.id===e.dataset.inspectEvidence);if(!ev)return;openModal(`<div class="pad"><div class="section-head"><div><div class="section-kicker">Evidence inspector</div><h2 id="modalTitle" style="margin:4px 0 0">${esc(ev.source)}</h2></div><button class="btn ghost" id="mc">Close</button></div><div class="inspector"><div class="section-kicker">Source</div><div style="margin-top:5px;font-weight:700">${esc(ev.type)} · ${esc(ev.date||'No date')}</div><div class="section-kicker" style="margin-top:16px">Observation</div><div style="margin-top:5px">${esc(ev.content)}</div><div class="meta"><span class="pill ${ev.stance==='supports'?'good':ev.stance==='contradicts'?'bad':''}">${esc(ev.stance||'neutral')}</span><span class="pill">Strength · ${esc(ev.strength||'medium')}</span></div><div class="section-kicker" style="margin-top:16px">Relationships</div><div style="margin-top:5px">${(ev.linked||[]).length?esc((ev.linked||[]).join(', ')):'No linked assumptions'}</div>${ev.url?`<div style="margin-top:12px"><a class="source" href="${esc(ev.url)}" target="_blank" rel="noreferrer">Open original source</a></div>`:''}</div></div>`);$('#mc').onclick=closeModal;track('evidence_inspected',{decision_id:d.id,evidence_id:ev.id})});bindDiscovery();bindEval();bindRag();bindExecution();bindStage4Governance({state,current,commit,track,render,toast,openModal,closeModal})}
function createDecision({title,problem,user,context}){const d={id:'d'+Date.now(),workflowState:'DRAFT',workflowStateVersion:1,workflowHistory:[],title,problem,user,context,status:'validate',createdAt:new Date().toISOString().slice(0,10),updatedAt:new Date().toISOString().slice(0,10),assumptions:[],evidence:[],challenges:[],alternatives:[],experiment:{hypothesis:'',control:'',intervention:'',primary:'',guardrails:[],baseline:'',target:'',prediction:'',successRule:'',failureRule:'',status:'draft'},prediction:{metric:'',predicted:null,confidence:50},outcome:{actual:null,notes:'',result:'pending'},learning:'',prd:'',jira:[]};state.decisions.unshift(d);decisionId=d.id;view='decisions';tab='overview';save();track('decision_created',{decision_id:d.id});render()}
function newDecision(){openModal(`<div class="pad"><div class="section-head"><div><div class="section-kicker">Guided decision</div><h2 id="modalTitle" style="margin:4px 0 0">Start with the decision, not the tooling</h2></div><button class="btn ghost" id="mc">Close</button></div><p class="sub">In two minutes, capture the decision your team needs to make. ThinkForge will then identify evidence gaps and the next best action.</p><div class="form" style="margin-top:18px"><div class="field"><label for="wizardTemplate">Decision type</label><select id="wizardTemplate"><option value="feature">Should we build a feature?</option><option value="problem">Which customer problem should we solve?</option><option value="experiment">Should we run an experiment?</option><option value="strategy">Should we make a strategic bet?</option></select></div><div class="field"><label for="wizardTitle">Decision title</label><input id="wizardTitle" maxlength="300" placeholder="e.g. Should we launch guided onboarding?"></div><div class="field"><label for="wizardProblem">Decision question and context</label><textarea id="wizardProblem" maxlength="5000" placeholder="What choice is being made, why now, and what outcome matters?"></textarea></div><div class="field"><label for="wizardUser">Target customer or stakeholder</label><input id="wizardUser" maxlength="300" placeholder="e.g. New B2B workspace admins"></div></div><div class="actions" style="margin-top:18px"><button class="btn primary" id="createGuidedDecision">Create decision</button></div></div>`);$('#mc').onclick=closeModal;$('#createGuidedDecision').onclick=()=>{const title=$('#wizardTitle').value.trim(),problem=$('#wizardProblem').value.trim(),user=$('#wizardUser').value.trim();if(!title||!problem){toast('Add a title and decision context to continue');return}const type=$('#wizardTemplate').value;createDecision({title,problem,user,context:`Decision type: ${type}. ${problem}`});closeModal();toast('Decision created — add evidence to strengthen it.')}}
function decisionBrief(d){const r=stage4Readiness(d);return `Decision: ${d.title}\n\nQuestion: ${d.problem||d.context||'Not defined'}\n\nRecommendation: ${d.status||'validate'}\nDecision health: ${Math.round(r.confidence*100)}% confidence · ${r.blockers.length} review blocker${r.blockers.length===1?'':'s'}\nEvidence: ${(d.evidence||[]).length} item${(d.evidence||[]).length===1?'':'s'}\nOpen assumptions: ${(d.assumptions||[]).filter(a=>a.status!=='validated').length}\n\nNext action: ${String(nextAction(d)).replace(/<[^>]+>/g,'')}`}
function openDecisionBrief(){const d=current();if(!d)return;const brief=decisionBrief(d);openModal(`<div class="pad"><div class="section-head"><div><div class="section-kicker">Shareable decision brief</div><h2 id="modalTitle" style="margin:4px 0 0">${esc(d.title)}</h2></div><button class="btn ghost" id="mc">Close</button></div><div class="banner ${stage4Readiness(d).readyForReview?'success':'warn'}"><strong>${stage4Readiness(d).readyForReview?'Ready for review':'Still investigating'}</strong><div class="note">${esc(nextAction(d).replace(/<[^>]+>/g,''))}</div></div><pre class="decision-brief">${esc(brief)}</pre><div class="actions" style="margin-top:16px"><button class="btn primary" id="copyBrief">Copy brief</button></div></div>`);$('#mc').onclick=closeModal;$('#copyBrief').onclick=async()=>{try{await navigator.clipboard.writeText(brief);toast('Decision brief copied')}catch{toast('Copy is unavailable in this browser')}};track('decision_brief_opened',{decision_id:d.id})}
function addAssumption(){openModal(`<div class="pad"><div class="section-head"><h2>Add assumption</h2><button class="btn ghost" id="mc">Close</button></div><div class="form"><div class="field"><label>Assumption</label><textarea id="at"></textarea></div><div class="grid g2"><div class="field"><label>Impact (1–5)</label><input id="ai" type="number" min="1" max="5" value="4"></div><div class="field"><label>Uncertainty (1–5)</label><input id="au" type="number" min="1" max="5" value="4"></div></div><button class="btn primary" id="as">Add</button></div></div>`);$('#mc').onclick=closeModal;$('#as').onclick=()=>{const d=current();d.assumptions.push({id:'a'+Date.now(),text:$('#at').value.trim(),impact:+$('#ai').value,uncertainty:+$('#au').value,confidence:.2,status:'open',rationale:'Manually added; evidence confidence starts low.'});save();track('assumption_added',{decision_id:d.id});closeModal();render()}}
function editAssumption(id){const a=current().assumptions.find(x=>x.id===id);openModal(`<div class="pad"><div class="section-head"><h2>Edit assumption</h2><button class="btn ghost" id="mc">Close</button></div><div class="form"><div class="field"><label>Text</label><textarea id="et">${esc(a.text)}</textarea></div><div class="grid g2"><div class="field"><label>Impact</label><input id="ei" type="number" min="1" max="5" value="${a.impact}"></div><div class="field"><label>Uncertainty</label><input id="eu" type="number" min="1" max="5" value="${a.uncertainty}"></div></div><button class="btn primary" id="es">Save</button></div></div>`);$('#mc').onclick=closeModal;$('#es').onclick=()=>{a.text=$('#et').value.trim();a.impact=+$('#ei').value;a.uncertainty=+$('#eu').value;save();closeModal();render()}}
function addEvidence(){const d=current();openModal(`<div class="pad"><div class="section-head"><h2>Add evidence</h2><button class="btn ghost" id="mc">Close</button></div><div class="form"><div class="grid g2"><div class="field"><label>Type</label><select id="et"><option>interview</option><option>analytics</option><option>survey</option><option>review</option><option>research</option><option>RAG</option></select></div><div class="field"><label>Source</label><input id="es" placeholder="Interview #7 / Analytics / URL source"></div></div><div class="field"><label>Evidence</label><textarea id="ec"></textarea></div><div class="grid g3"><div class="field"><label>Stance</label><select id="est"><option>supports</option><option>contradicts</option><option>neutral</option></select></div><div class="field"><label>Strength</label><select id="estr"><option>strong</option><option selected>medium</option><option>weak</option></select></div><div class="field"><label>Source URL</label><input id="eu"></div></div><button class="btn primary" id="as">Add evidence</button></div></div>`);$('#mc').onclick=closeModal;$('#as').onclick=()=>{d.evidence.push({id:'e'+Date.now(),type:$('#et').value,source:$('#es').value.trim()||'User-entered source',content:$('#ec').value.trim(),stance:$('#est').value,strength:$('#estr').value,date:new Date().toISOString().slice(0,10),linked:[],url:$('#eu').value.trim()});save();track('evidence_added',{decision_id:d.id,type:$('#et').value});closeModal();render()}}
function addAlternative(){const d=current();openModal(`<div class="pad"><div class="section-head"><h2>Add option</h2><button class="btn ghost" id="mc">Close</button></div><div class="form"><div class="field"><label>Name</label><input id="on"></div><div class="grid g4"><div class="field"><label>Impact</label><input id="oi" type="number" min="1" max="10" value="5"></div><div class="field"><label>Effort</label><input id="oe" type="number" min="1" max="10" value="5"></div><div class="field"><label>Risk</label><input id="or" type="number" min="1" max="10" value="5"></div><div class="field"><label>Evidence</label><input id="ob" type="number" min="1" max="10" value="5"></div></div><div class="field"><label>Reversibility</label><input id="ov" type="number" min="1" max="10" value="5"></div><button class="btn primary" id="ao">Add option</button></div></div>`);$('#mc').onclick=closeModal;$('#ao').onclick=()=>{d.alternatives.push({name:$('#on').value.trim(),impact:+$('#oi').value,effort:+$('#oe').value,risk:+$('#or').value,evidence:+$('#ob').value,reversibility:+$('#ov').value});save();closeModal();render()}}
function saveExperiment(){const d=current();d.experiment.hypothesis=$('#exHyp').value.trim();d.experiment.control=$('#exCtl').value.trim();d.experiment.intervention=$('#exInt').value.trim();d.experiment.primary=$('#exPrimary').value.trim();d.experiment.guardrails=$('#exGuard').value.split(',').map(x=>x.trim()).filter(Boolean);d.experiment.successRule=$('#exSuccess').value.trim();d.experiment.failureRule=$('#exFail').value.trim();d.prediction={metric:d.experiment.primary,predicted:+$('#exPred').value||null,confidence:d.prediction?.confidence||50};d.experiment.status='planned';save();track('experiment_created',{decision_id:d.id});toast('Experiment saved');render()}
function saveOutcome(){const d=current();d.outcome.actual=$('#outActual').value===''?null:+$('#outActual').value;d.outcome.result=$('#outResult').value;d.learning=$('#outLearning').value.trim();save();track('outcome_recorded',{decision_id:d.id,result:d.outcome.result});toast('Outcome recorded');render()}

function offlineAi(action,d){const topic=(d.title||d.problem||'the decision').replace(/[.?!]/g,'').slice(0,110),evidence=(d.evidence||[]).map(x=>x.id).filter(Boolean);if(action==='assumptions')return{assumptions:[{text:`${topic} addresses a meaningful customer problem.`,impact:5,uncertainty:4,confidence:.35,rationale:'Deterministic demo assumption; validate with real evidence.',evidence_refs:evidence.slice(0,2)},{text:'The proposed intervention can improve the primary outcome without material guardrail harm.',impact:5,uncertainty:4,confidence:.25,rationale:'Deterministic demo assumption; requires an experiment.',evidence_refs:[]}]};if(action==='challenge')return{challenges:[{priority:1,assumption:`${topic} addresses the primary user constraint.`,question:'Which observed evidence distinguishes this problem from alternative causes?',why:'The decision could change if the root cause is different.',evidence_refs:evidence.slice(0,2)},{priority:2,assumption:'The target segment will adopt the intervention.',question:'What smallest reversible test can measure adoption?',why:'Adoption determines whether a build is justified.',evidence_refs:[]},{priority:3,assumption:'The intervention is safe to scale.',question:'Which guardrail could worsen while the primary metric improves?',why:'A local gain can hide a customer-cost trade-off.',evidence_refs:[]}]};if(action==='experiment')return{experiment:{hypothesis:`For the target segment, a small intervention related to ${topic} improves the primary outcome.`,control:'Current experience',intervention:'Smallest reversible prototype or concierge test',primary:'Completion or activation rate',guardrails:['Support contacts','Abandonment rate'],baseline:'Measure before launch',target:'Pre-register a directional target',prediction:'No numeric prediction in offline demo',successRule:'Improve the primary metric without guardrail regression.',failureRule:'No meaningful improvement or a guardrail worsens.',status:'draft'}};if(action==='synthesize')return{summary:`Offline demo synthesis for ${topic}. Review supplied evidence and unresolved assumptions before deciding.`,recommendation:'validate',evidence_gaps:['Collect real participant evidence and a baseline metric.'],next_action:'Run the smallest reversible experiment.',confidence:.25};if(action==='prd')return{title:topic,problem:d.problem||'Define the problem',targetUser:d.user||'Target segment',evidence:evidence,assumptions:(d.assumptions||[]).map(x=>x.text),decision:'validate',scope:['Build a smallest testable intervention'],outOfScope:['Irreversible rollout'],metrics:{primary:'Completion or activation rate',secondary:[],guardrails:['Support contacts']},experiment:'Run a reversible test first.',openQuestions:['What real evidence would change this decision?']};return null}
async function ai(action){const d=current();const started=startMeasure(`ai_${action}`);aiState={status:'working',label:`Analyzing ${action}…`,action};announce(aiState.label);render();let x,model='provider';try{const r=await apiPost('/api/ai',{action,decision:d}),j=await r.json();if(!r.ok)throw new Error(j.error||'AI not configured');x=j.data;model=j.meta?.model||'provider'}catch(e){if(!state.settings.offlineDemo){aiState={status:'error',label:e.message||'AI unavailable',action};announce(aiState.label);toast(aiState.label);render();return}x=offlineAi(action,d);model='deterministic-demo';toast('Offline demo result — validate with real evidence')}if(action==='assumptions'&&x?.assumptions)d.assumptions=(x.assumptions||[]).map((a,i)=>({id:'a'+Date.now()+i,...a,status:'open'}));if(action==='challenge'&&x?.challenges)d.challenges=x.challenges;if(action==='experiment'&&x?.experiment){d.experiment={...d.experiment,...x.experiment,status:'planned'};d.prediction={metric:x.experiment.primary,predicted:null,confidence:0}}if(action==='synthesize'&&x)d.status=x.recommendation;if(action==='prd'&&x)d.prd=JSON.stringify(x,null,2);save();track('ai_action',{action,decision_id:d.id,model,duration_ms:Math.round(performance.now()-started.started)});aiState={status:'success',label:model==='deterministic-demo'?'Offline demo ready for review':'Analysis ready for review',action};announce(aiState.label);render();setTimeout(()=>{aiState={status:'idle',label:'',action};render()},1200)}

function ensureDiscovery(){state.research=state.research||{};state.research.version=state.research.version||2;state.research.hypotheses=state.research.hypotheses||[];state.research.interviews=state.research.interviews||[];state.research.findings=state.research.findings||[];state.research.evidence=state.research.evidence||[];state.research.codes=state.research.codes||[];state.research.themes=state.research.themes||[];state.research.opportunities=state.research.opportunities||[];state.research.solutions=state.research.solutions||[];state.research.assumptions=state.research.assumptions||[];state.research.segments=state.research.segments||[];state.research.tests=state.research.tests||[];state.research.webSources=state.research.webSources||[];state.research.humanEvidence=state.research.humanEvidence||[];state.research.deepResearch=state.research.deepResearch||null;state.research.discovery={...(state.research.discovery||{}),desiredOutcome:state.research.discovery?.desiredOutcome||'',researchQuestion:state.research.discovery?.researchQuestion||'',questionType:state.research.discovery?.questionType||'exploratory',method:state.research.discovery?.method||'interview',segments:state.research.discovery?.segments||[],constraints:state.research.discovery?.constraints||[],decision:state.research.discovery?.decision||'',timeHorizon:state.research.discovery?.timeHorizon||''};return state.research}
function discoveryBundle(){const r=ensureDiscovery();return{...r.discovery,evidence:r.evidence,interviews:r.interviews,findings:r.findings,codes:r.codes,opportunities:r.opportunities,solutions:r.solutions,assumptions:r.assumptions,segments:r.segments,webSources:r.webSources,humanEvidence:r.humanEvidence}}
function discoveryBadge(status){return status==='READY'?'<span class="pill good">READY</span>':status==='BLOCK'?'<span class="pill bad">BLOCK</span>':'<span class="pill warn">INVESTIGATE</span>'}
function localAnalyzeDiscovery(b){const q=String(b.researchQuestion||'').toLowerCase();const qt=/why|cause|driver|because|impact|effect/.test(q)?'causal':/how many|how often|rate|percentage|distribution/.test(q)?'descriptive':/would|prototype|usability|evaluate|compare|does .* improve/.test(q)?'evaluative':/what could|how might|ideas|generate/.test(q)?'generative':/will|predict|forecast|likely/.test(q)?'predictive':/root cause|diagnose|why did/.test(q)?'diagnostic':'exploratory';const ev=(b.evidence||[]).map(e=>({...e,sourceType:e.sourceType||e.type||'manual',confidence:Math.max(0,Math.min(1,Number(e.confidence)>1?Number(e.confidence)/10:Number(e.confidence)||.5))}));const methods=[...new Set(ev.map(x=>x.sourceType))],participants=[...new Set(ev.map(x=>x.participantId).filter(Boolean))],segments=[...new Set(ev.map(x=>x.segment).filter(Boolean))];const avg=ev.length?ev.reduce((a,e)=>a+(e.strength==='strong'?.85:e.strength==='weak'?.45:.65),0)/ev.length:0;const pos=/\b(like|easy|useful|valuable|want|prefer|trust|safe)\b/i,neg=/\b(dislike|hard|confus|difficult|friction|problem|avoid|abandon|unsafe|don't trust)\b/i;const contradictions=[];for(let i=0;i<ev.length;i++)for(let j=i+1;j<ev.length;j++){const a=ev[i],c=ev[j],conflict=(a.stance==='supports'&&c.stance==='contradicts')||(a.stance==='contradicts'&&c.stance==='supports')||(pos.test(a.content||'')&&neg.test(c.content||''))||(neg.test(a.content||'')&&pos.test(c.content||''));if(conflict)contradictions.push({id:'C-'+i+'-'+j,evidenceA:a.id,evidenceB:c.id,reason:'Potential opposing findings; review context and measurement differences.',severity:'medium',requiresHumanReview:true});}const counts={};ev.forEach(e=>String(e.content||'').toLowerCase().split(/[^a-z0-9]+/).filter(x=>x.length>4&&!['users','about','there','their','which','would','could'].includes(x)).forEach(w=>counts[w]=(counts[w]||0)+1));const themes=Object.entries(counts).filter(([,n])=>n>1).sort((a,c)=>c[1]-a[1]).slice(0,8).map(([label,count],i)=>({id:'T-'+label+'-'+i,label,count,evidenceIds:ev.filter(e=>String(e.content||'').toLowerCase().includes(label)).map(e=>e.id),confidence:Math.min(.95,.45+count*.1),status:'candidate'}));const fitMap={causal:['experiment','behavioral_analytics'],exploratory:['interview','contextual_inquiry','diary_study'],descriptive:['survey','behavioral_analytics'],evaluative:['usability_test','prototype_test','experiment'],generative:['interview','contextual_inquiry'],predictive:['behavioral_analytics','experiment'],diagnostic:['behavioral_analytics','support_ticket_analysis']};const fitMethod=b.method||'interview',fit=(fitMap[qt]||[]).includes(fitMethod)?'HIGH':'LOW';const gaps=[];if(ev.length<3)gaps.push({id:'G-evidence',requirement:'at least three evidence items',severity:'high'});if(methods.length<2)gaps.push({id:'G-methods',requirement:'independent method/source coverage',severity:'medium'});if(!segments.length)gaps.push({id:'G-segments',requirement:'segment coverage',severity:'medium'});if(qt==='causal'&&!methods.includes('experiment'))gaps.push({id:'G-causal',requirement:'comparator/counterfactual evidence',severity:'high'});if(contradictions.length)gaps.push({id:'G-contradictions',requirement:'contradiction resolution',severity:'high'});const opps=themes.slice(0,6).map((t,i)=>{const confidence=Math.max(0,Math.min(1,.4+.12*t.count+.2*avg-(contradictions.length*.05)));return{id:'OPP-'+i,label:t.label,evidenceIds:t.evidenceIds,customerImportance:6,customerReach:segments.length?7:5,strategicRelevance:6,marketRelevance:5,confidence:Number(confidence.toFixed(3)),score:Number((10*(.25*.6+.15*(segments.length?.7:.5)+.2*.6+.1*.5+.3*confidence)).toFixed(2))}});const assumptions=opps.slice(0,5).map(o=>{const importance=Math.min(10,4+o.score/2),uncertainty=Number((10-o.confidence*10).toFixed(1)),evidenceStrength=Number((o.confidence*10).toFixed(1)),costOfError=o.score>=7?8:5;return{id:'A-'+o.id.replace('OPP-',''),opportunityId:o.id,text:`Users will experience enough value from addressing “${o.label}” to improve the desired outcome.`,assumptionType:'desirability',importance,uncertainty,evidenceStrength,costOfError,leapOfFaith:o.confidence<.5,risk:Number((40*importance/10+30*uncertainty/10+20*(1-o.confidence)+10*(costOfError/10)).toFixed(1))}});const solutions=opps.flatMap(o=>[{id:'SOL-'+o.id+'-direct',opportunityId:o.id,title:`Improve the core experience for ${o.label}`,status:'candidate',description:'Smallest viable product change.'},{id:'SOL-'+o.id+'-manual',opportunityId:o.id,title:`Test an assisted path for ${o.label}`,status:'candidate',description:'Low-cost validation before deep implementation.'},{id:'SOL-'+o.id+'-trust',opportunityId:o.id,title:`Improve guidance and trust around ${o.label}`,status:'candidate',description:'Reduce uncertainty with clearer feedback and explanation.'}]);const status=!b.desiredOutcome||!b.researchQuestion?'BLOCK':(contradictions.length||gaps.some(g=>g.severity==='high')||avg<.5||assumptions.some(a=>a.leapOfFaith))?'INVESTIGATE':'READY';return{questionType:qt,questionUnderstanding:{type:qt,confidence:.78,decisionImpact:['causal','evaluative','predictive','diagnostic'].includes(qt)?'high':'medium'},methodFit:{fit,score:fit==='HIGH'?5:2,method:fitMethod,questionType:qt,rationale:fit==='HIGH'?`Strong fit for ${qt}.`:`Consider ${fitMap[qt]?.slice(0,2).join(' / ')||'another method'} and triangulate.`},evidence:ev,themes,coverage:{participants:participants.length,segments:segments.length,methods:methods.length},triangulation:{status:methods.length>=3?'CONVERGING':methods.length>=2?'TRIANGULATED':'SINGLE_METHOD',methodCount:methods.length},evidenceQuality:{aggregate:Number(avg.toFixed(3)),items:ev.map(e=>({id:e.id,score:avg}))},evidenceGaps:gaps,contradictions,opportunities:opps,assumptions,solutions,ost:{type:'outcome',label:b.desiredOutcome||'Desired outcome',children:opps.map(o=>({id:o.id,type:'opportunity',label:o.label,confidence:o.confidence,score:o.score,evidenceIds:o.evidenceIds,children:solutions.filter(s=>s.opportunityId===o.id)}))},gate:{status,errors:[!b.desiredOutcome?'desired_outcome_missing':null,!b.researchQuestion?'research_question_missing':null].filter(Boolean),warnings:[...new Set(gaps.map(g=>g.requirement))],criticalAssumptions:assumptions.filter(a=>a.leapOfFaith),nextAction:status==='READY'?'Promote to a decision or test a solution.':'Close the highest-impact evidence gap first.'},downstream:{decisionSeed:{title:b.desiredOutcome||'Discovery-derived decision',problem:b.researchQuestion||'',status:'validate'},assumptionIds:assumptions.map(a=>a.id),opportunityIds:opps.map(o=>o.id),solutionIds:solutions.map(s=>s.id),evidenceIds:ev.map(e=>e.id),experimentSeeds:assumptions.filter(a=>a.leapOfFaith).map(a=>({assumptionId:a.id,hypothesis:a.text,testType:'lowest-cost-credible-test'}))},generatedAt:new Date().toISOString()};}
async function runDeepResearch(){const r=ensureDiscovery();if(!r.discovery.desiredOutcome||!r.discovery.researchQuestion)return toast('Set the desired outcome and research question first');try{const resp=await apiPost('/api/discovery',{action:'deep_research',bundle:{...r.discovery,evidence:r.evidence,webSources:r.webSources,humanEvidence:r.humanEvidence,decisionImpact:'high'}});const j=await resp.json();if(!resp.ok)throw new Error(j.error||'Deep research failed');r.deepResearch=j.result;r.analysis=j.result.analysis||r.analysis;r.themes=r.analysis?.themes||r.themes;r.opportunities=r.analysis?.opportunities||r.opportunities;r.assumptions=r.analysis?.assumptions||r.assumptions;r.solutions=r.analysis?.solutions||r.solutions;save();track('discovery_deep_research_completed',{status:j.result.status,independent_sources:j.result.quality?.sources?.independent||0});toast(`Deep research: ${j.result.status}`,true);render()}catch(e){toast(e.message||'Deep research unavailable')}}
function openHumanEvidence(){openModal(`<div class="pad"><h2>Add human research</h2><div class="banner">Only real participant responses can become empirical evidence. Synthetic/persona responses are permanently labelled and excluded from empirical claims.</div><div class="form"><div class="grid g2"><div class="field"><label>Participant ID</label><input id="hp"></div><div class="field"><label>Segment</label><input id="hs"></div></div><div class="grid g2"><div class="field"><label>Method</label><select id="hm"><option>interview</option><option>survey</option><option>usability</option><option>customer_call</option><option>support</option></select></div><div class="field"><label>Date</label><input id="hd" type="date" value="${new Date().toISOString().slice(0,10)}"></div></div><div class="field"><label>Response / observation</label><textarea id="hr"></textarea></div><button class="btn primary" id="hsv">Save human evidence</button></div></div>`);$('#hsv').onclick=()=>{const r=ensureDiscovery();r.humanEvidence.push({id:'H-'+Date.now(),participantId:$('#hp').value.trim(),segment:$('#hs').value.trim(),method:$('#hm').value,date:$('#hd').value,response:$('#hr').value.trim(),consentRecorded:true,evidenceStatus:'REAL'});save();closeModal();render()}}
function openWebSources(){openModal(`<div class="pad"><h2>Import web research sources</h2><div class="banner">For live 60+ source sweeps configure <code>TAVILY_API_KEY</code>. This importer accepts provider output or curated sources; duplicates are clustered by canonical URL/underlying study.</div><div class="field"><label>JSON array of sources</label><textarea id="ws" style="min-height:260px" placeholder='[{"url":"https://example.com","title":"Source","sourceClass":"academic","content":"Evidence..."}]'></textarea></div><button class="btn primary" id="wsv">Import sources</button></div>`);$('#wsv').onclick=()=>{try{const items=JSON.parse($('#ws').value||'[]');if(!Array.isArray(items))throw new Error('Expected a JSON array');const r=ensureDiscovery();r.webSources.push(...items);save();closeModal();render();toast(`${items.length} sources imported`,true)}catch(e){toast(e.message)}}}
async function persistDiscoveryCanonical(){const r=ensureDiscovery();if(!r.discovery.desiredOutcome&&!r.discovery.researchQuestion)return;try{const resp=await apiPost('/api/discovery',{action:'save',record:{id:r.discovery.id||'DISC-'+Date.now(),...r.discovery,status:r.analysis?.gate?.status||'DRAFT',evidence:r.evidence,codes:r.analysis?.codes||r.codes,themes:r.analysis?.themes||r.themes,opportunities:r.analysis?.opportunities||r.opportunities,solutions:r.analysis?.solutions||r.solutions,webSources:r.webSources,humanEvidence:r.humanEvidence,deepResearch:r.deepResearch,analysisPayload:r.analysis||{}}});if(resp.ok){const j=await resp.json();r.discovery.id=j.id||r.discovery.id||null;r.discovery.sourceOfTruth='relational';r.discovery.analysisVersion=j.analysisVersion||'stage1-v14.1';localSave()}}catch(e){console.warn('Discovery canonical persistence failed',e)}}
function promoteDiscoveryToDecision(){const r=ensureDiscovery(),a=r.analysis;if(!a?.opportunities?.length)return toast('Run discovery analysis first');const o=a.opportunities[0],now=new Date().toISOString().slice(0,10),d={id:'d-'+Date.now(),title:r.discovery.desiredOutcome||o.label,problem:r.discovery.researchQuestion||o.label,user:'Discovery-derived segment',context:'Promoted from Stage 1 discovery evidence.',status:'validate',createdAt:now,updatedAt:now,assumptions:(a.assumptions||[]).slice(0,5).map(x=>({id:x.id,text:x.text,impact:x.importance,uncertainty:x.uncertainty,confidence:(x.evidenceStrength||0)/10,status:x.leapOfFaith?'open':'needs_validation',rationale:`Derived from opportunity ${o.id}`,source:'stage1'})),evidence:(a.evidence||[]).map(e=>({id:e.id,type:e.sourceType,source:e.sourceId||'Discovery',content:e.content,stance:e.stance,strength:e.strength,date:e.date,linked:[]})),challenges:[],alternatives:(a.solutions||[]).filter(s=>s.opportunityId===o.id).map(s=>({name:s.title,impact:Number(o.score||5),effort:5,risk:s.riskScore||5,evidence:Number(o.confidence||.5)*10,reversibility:8})),experiment:{hypothesis:a.downstream?.experimentSeeds?.[0]?.hypothesis||`Test whether addressing ${o.label} improves the desired outcome.`,control:'Current experience',intervention:'Lowest-cost credible test',primary:'Outcome metric',guardrails:[],baseline:'',target:'',prediction:'',successRule:'',failureRule:'',status:'draft'},prediction:{metric:'Outcome metric',predicted:null,confidence:0},outcome:{actual:null,notes:'',result:'pending'},learning:'',prd:'',jira:[]};state.decisions.unshift(d);decisionId=d.id;view='decisions';save();track('discovery_promoted_to_decision',{decision_id:d.id,opportunity_id:o.id});toast('Discovery promoted to decision');render();}

function renderDiscovery(){const r=ensureDiscovery();const a=r.analysis||{};const gate=a.gate||{status:'INVESTIGATE',warnings:['Run analysis to assess discovery quality.'],errors:[]};const opps=(a.opportunities||r.opportunities||[]);const themes=(a.themes||r.themes||[]);const contradictions=a.contradictions||[];const cov=a.coverage||{};const tri=a.triangulation||{};return top('Stage 1','Product discovery','Outcome-first, evidence-backed discovery with provenance, contradiction checks, opportunity mapping and assumption tests.',`<button class="btn primary" id="analyzeDiscovery">Analyze discovery</button><button class="btn primary" id="deepResearch">Deep Research 60+</button><button class="btn" id="addHumanEvidence">+ Human evidence</button><button class="btn" id="importWebSources">+ Web sources</button><button class="btn" id="promoteDiscovery">Promote to decision</button><button class="btn" id="addEvidenceD">+ Evidence</button><button class="btn" id="addInterview">+ Research session</button><button class="btn" id="addFinding">+ Finding</button>`)+`<div class="banner"><strong>Discovery quality rule:</strong> AI may suggest structure, but evidence, quotes and researcher interpretations remain distinct. Research is not marked ready when critical contradictions or leap-of-faith assumptions remain.</div><div class="grid g3"><div class="card pad"><div class="section-head"><h2>Discovery brief</h2>${discoveryBadge(gate.status)}</div><div class="form"><div class="field"><label>Desired outcome</label><textarea id="dOutcome" placeholder="What product outcome are we trying to change?">${esc(r.discovery.desiredOutcome)}</textarea></div><div class="field"><label>Research question</label><textarea id="rQuestion" placeholder="What do we need to learn to decide?">${esc(r.discovery.researchQuestion)}</textarea></div><div class="grid g2"><div class="field"><label>Target segments</label><input id="dSegments" placeholder="SMB, Enterprise" value="${esc((r.discovery.segments||[]).join(", "))}"></div><div class="field"><label>Constraints</label><input id="dConstraints" placeholder="Budget, time, policy" value="${esc((r.discovery.constraints||[]).join(", "))}"></div></div><div class="grid g2"><div class="field"><label>Question type</label><select id="qType"><option>exploratory</option><option>descriptive</option><option>evaluative</option><option>causal</option><option>predictive</option><option>generative</option></select></div><div class="field"><label>Primary method</label><select id="rMethod"><option>interview</option><option>contextual_inquiry</option><option>usability_test</option><option>prototype_test</option><option>survey</option><option>diary_study</option><option>behavioral_analytics</option><option>support_ticket_analysis</option><option>competitive_research</option><option>experiment</option></select></div></div><button class="btn primary" id="saveBrief">Save brief</button></div></div><div class="card pad"><div class="section-head"><h2>Research quality</h2><span class="pill">${gate.warnings?.length||0} warnings</span></div><div class="list"><div class="item"><strong>Method fit</strong><div class="note">${a.methodFit?.fit||'—'} ${a.methodFit?.rationale?`· ${esc(a.methodFit.rationale)}`:''}</div></div><div class="item"><strong>Evidence coverage</strong><div class="note">${cov.participants||0} participants · ${cov.segments||0} segments · ${cov.methods||0} methods</div></div><div class="item"><strong>Triangulation</strong><div class="note">${tri.status||'—'} · ${tri.methodCount||0} method types</div></div>${(gate.warnings||[]).slice(0,5).map(x=>`<div class="item"><strong>⚠ ${esc(x)}</strong></div>`).join('')}</div></div><div class="card pad"><div class="section-head"><h2>Discovery metrics</h2><span class="pill good">traceable</span></div><div class="grid g2"><div class="mini"><strong>${r.evidence.length}</strong><div class="note">Evidence</div></div><div class="mini"><strong>${r.interviews.length}</strong><div class="note">Research sessions</div></div><div class="mini"><strong>${themes.length}</strong><div class="note">Themes</div></div><div class="mini"><strong>${contradictions.length}</strong><div class="note">Contradictions</div></div></div></div><div class="item"><strong>Evidence quality</strong><div class="note">${a.evidenceQuality?.aggregate===undefined?"—":Math.round((a.evidenceQuality.aggregate||0)*100)+"%"} aggregate · ${a.evidenceGaps?.length||0} gaps</div></div><div class="item"><strong>Downstream readiness</strong><div class="note">${a.downstream?.opportunityIds?.length||opps.length} opportunities · ${a.downstream?.assumptionIds?.length||r.assumptions.length} assumptions · ${a.downstream?.experimentSeeds?.length||0} test seeds</div></div></div></div><div class="section card pad"><div class="section-head"><h2>Deep Research</h2><span class="pill">v5 · 60+ independent target</span></div><div class="grid g4"><div class="mini"><strong>${a.deepResearch?.quality?.sources?.independent||r.deepResearch?.quality?.sources?.independent||0}</strong><div class="note">Independent sources</div></div><div class="mini"><strong>${a.deepResearch?.quality?.sources?.duplicates||r.deepResearch?.quality?.sources?.duplicates||0}</strong><div class="note">Duplicates clustered</div></div><div class="mini"><strong>${a.deepResearch?.quality?.humanResearch?.real||r.deepResearch?.quality?.humanResearch?.real||r.humanEvidence.length}</strong><div class="note">Real human evidence</div></div><div class="mini"><strong>${r.deepResearch?.status||'NOT RUN'}</strong><div class="note">Research status</div></div></div><div class="note" style="margin-top:10px">${r.deepResearch?.quality?.sourceDiversity?`Source diversity ${Math.round(r.deepResearch.quality.sourceDiversity.diversityScore*100)}% · Saturation ${r.deepResearch.saturation?.saturated?'reached':'not reached'}`:'Run Deep Research to execute the multi-source protocol.'}</div></div><div class="section card pad"><div class="section-head"><h2>Discovery intelligence</h2><span class="pill">v5</span></div><div class="grid g4"><div class="mini"><strong>${Math.round((a.questionQuality?.score||0)*100)}%</strong><div class="note">Question quality</div></div><div class="mini"><strong>${Math.round((tri.confidence||0)*100)}%</strong><div class="note">Triangulation confidence</div></div><div class="mini"><strong>${tri.independentUnits||0}</strong><div class="note">Independent evidence units</div></div><div class="mini"><strong>${a.stopCondition?.status==='STOP_READY'?'READY':'LEARN'}</strong><div class="note">Discovery stop condition</div></div></div><div class="grid g2" style="margin-top:12px"><div class="item"><strong>Question quality</strong><div class="note">${(a.questionQuality?.issues||[]).join(' · ')||'No quality issues detected.'}</div>${a.questionQuality?.rewrite?`<div class="note" style="margin-top:5px"><strong>Suggested:</strong> ${esc(a.questionQuality.rewrite)}</div>`:''}</div><div class="item"><strong>Next best discovery actions</strong><div class="note">${(a.nextActions||[]).slice(0,4).map(x=>`${esc(x.priority)} · ${esc(x.action)}`).join('<br>')||'Analyze discovery to generate actions.'}</div></div></div></div><div class="section card pad"><div class="section-head"><h2>Segment coverage</h2><span class="pill">${(a.segmentInsights||[]).length}</span></div><div class="grid g3">${(a.segmentInsights||[]).slice(0,6).map(x=>`<div class="mini"><strong>${esc(x.segment)}</strong><div class="note">${x.evidenceCount} evidence · ${x.methodCount} methods · ${Math.round((x.quality||0)*100)}% quality</div><div class="note">${x.themes?.map(esc).join(' · ')||'No themes yet'}</div></div>`).join('')||'<div class="empty">Add segmented evidence to see coverage.</div>'}</div></div><div class="section grid g2"><div class="card pad"><div class="section-head"><h2>Evidence & inference ladder</h2><span class="pill">${r.evidence.length}</span></div><div class="list">${r.evidence.slice(-8).reverse().map(e=>`<div class="item"><div class="item-head"><strong>${esc(e.level||'FACT')} · ${esc(e.content||'')}</strong><span class="pill ${e.stance==='contradicts'?'bad':e.stance==='supports'?'good':''}">${esc(e.stance||'neutral')}</span></div><div class="note">${esc(e.sourceType||'research')} · ${esc(e.participantId||'no participant')} · ${esc(e.segment||'no segment')}</div>${e.quote?`<div class="note">“${esc(e.quote)}”</div>`:''}</div>`).join('')||'<div class="empty">Add raw evidence. Do not start with an AI summary.</div>'}</div><div class="card pad"><div class="section-head"><h2>Codes & themes</h2><span class="pill">${themes.length}</span></div><div class="list">${themes.map(t=>`<div class="item"><div class="item-head"><strong>${esc(t.label)}</strong><span class="pill">${t.count}</span></div><div class="note">${esc(t.strength)} · ${t.evidenceIds?.length||0} linked evidence items</div></div>`).join('')||'<div class="empty">Analyze evidence to surface candidate themes.</div>'}</div></div></div><div class="section grid g2"><div class="card pad"><div class="section-head"><h2>Contradictions</h2><span class="pill ${contradictions.length?'warn':'good'}">${contradictions.length}</span></div><div class="list">${contradictions.map(c=>`<div class="item"><strong>${esc(c.evidenceA)} ↔ ${esc(c.evidenceB)}</strong><div class="note">${esc(c.reason)} · ${esc(c.severity)}</div><div class="note">${esc(c.resolution)}</div></div>`).join('')||'<div class="empty">No contradictory evidence detected in the current evidence set.</div>'}</div></div><div class="card pad"><div class="section-head"><h2>Opportunity Solution Tree</h2><span class="pill">Outcome → opportunities → solutions → tests</span></div><div class="ost"><div class="ost-root"><strong>${esc(r.discovery.desiredOutcome||'Set a desired outcome')}</strong></div>${opps.slice(0,6).map(o=>`<div class="ost-branch"><div class="item"><div class="item-head"><strong>${esc(o.label||o.text)}</strong><span class="pill good">${Number(o.score||0).toFixed(1)}</span></div><div class="note">Evidence: ${(o.evidenceIds||[]).length} · Customer importance ${o.customerImportance??'—'} · Evidence strength ${o.evidenceStrength??'—'}</div>${r.solutions.filter(s=>s.opportunityId===o.id).map(s=>`<div class="note">↳ ${esc(s.label||s.name)}</div>`).join('')}</div></div>`).join('')||'<div class="empty">Run analysis to generate evidence-backed opportunities.</div>'}</div></div></div><div class="section card pad"><div class="section-head"><h2>Discovery gate</h2>${discoveryBadge(gate.status)}</div><div class="grid g3"><div class="item"><strong>Core inputs</strong><div class="note">${gate.errors?.length?'Missing '+gate.errors.length:'Complete'}</div></div><div class="item"><strong>Critical uncertainties</strong><div class="note">${(gate.criticalAssumptions||[]).length}</div></div><div class="item"><strong>Next action</strong><div class="note">${gate.status==='READY'?'Convert discovery into a decision.':'Collect evidence, resolve contradictions or test the riskiest assumption.'}</div></div></div></div>`}
function bindDiscovery(){ensureDiscovery();$('#saveBrief')?.addEventListener('click',(e)=>withBusy(e.currentTarget,async()=>{const r=ensureDiscovery();r.discovery.desiredOutcome=$('#dOutcome').value.trim();r.discovery.researchQuestion=$('#rQuestion').value.trim();r.discovery.segments=$('#dSegments').value.split(',').map(x=>x.trim()).filter(Boolean);r.discovery.constraints=$('#dConstraints').value.split(',').map(x=>x.trim()).filter(Boolean);r.discovery.questionType=$('#qType').value;r.discovery.method=$('#rMethod').value;save();await persistDiscoveryCanonical();track('discovery_brief_saved',{question_type:r.discovery.questionType,method:r.discovery.method});toast('Discovery brief saved');render()}));$('#qType')&&($('#qType').value=state.research.discovery.questionType);$('#rMethod')&&($('#rMethod').value=state.research.discovery.method);$('#analyzeDiscovery')?.addEventListener('click',(e)=>withBusy(e.currentTarget,async()=>{try{const r=ensureDiscovery();const body={action:'analyze',bundle:{...r.discovery,id:r.discovery.id,evidence:r.evidence,codes:r.codes,opportunities:r.opportunities,solutions:r.solutions,assumptions:r.assumptions,segments:r.segments,constraints:r.discovery.constraints||[],decision:r.discovery.decision||null,timeHorizon:r.discovery.timeHorizon||null}};let j=null;try{const resp=await apiPost('/api/discovery',body);j=await resp.json();if(!resp.ok)throw new Error(j.error||'Discovery analysis failed')}catch(err){try{const fallback=await apiPost('/api/discovery',{action:'analyze',mode:'heuristic',bundle:body.bundle});j=await fallback.json();if(!fallback.ok)throw new Error(j.error||err.message)}catch(fallbackErr){j={result:localAnalyzeDiscovery(body.bundle)}}}r.analysis=j.result||j;r.themes=r.analysis.themes||r.themes;r.opportunities=r.analysis.opportunities||r.opportunities;r.assumptions=r.analysis.assumptions||r.assumptions;r.solutions=r.analysis.solutions||r.solutions;save();await persistDiscoveryCanonical();track('discovery_analyzed',{status:r.analysis.gate?.status||'UNKNOWN',warnings:r.analysis.gate?.warnings?.length||0});toast(`Discovery ${r.analysis.gate?.status||'analyzed'}`);render()}catch(e){toast(e.message)}}));$('#promoteDiscovery')?.addEventListener('click',promoteDiscoveryToDecision);$('#addEvidenceD')?.addEventListener('click',()=>openDiscoveryEvidence());$('#addInterview')?.addEventListener('click',()=>openDiscoveryInterview());$('#addFinding')?.addEventListener('click',()=>openDiscoveryFinding());$('#deepResearch')?.addEventListener('click',()=>runDeepResearch());$('#addHumanEvidence')?.addEventListener('click',()=>openHumanEvidence());$('#importWebSources')?.addEventListener('click',()=>openWebSources())}
function openDiscoveryEvidence(){openModal(`<div class="pad"><h2>Capture raw evidence</h2><div class="banner warn">Record what was observed or said. Interpretation belongs in a separate field.</div><div class="form"><div class="grid g2"><div class="field"><label>Level</label><select id="elv"><option>FACT</option><option>OBSERVATION</option><option>INTERPRETATION</option><option>OPPORTUNITY</option><option>HYPOTHESIS</option></select></div><div class="field"><label>Source type</label><select id="est"><option>interview</option><option>contextual_inquiry</option><option>usability_test</option><option>survey</option><option>behavioral_analytics</option><option>support_ticket_analysis</option><option>competitive_research</option></select></div></div><div class="field"><label>Evidence / observation</label><textarea id="edc"></textarea></div><div class="field"><label>Quote (optional)</label><textarea id="eqt"></textarea></div><div class="grid g3"><div class="field"><label>Participant ID</label><input id="ep"></div><div class="field"><label>Segment</label><input id="esg"></div><div class="field"><label>Stance</label><select id="esn"><option>supports</option><option>contradicts</option><option>neutral</option></select></div></div><div class="grid g2"><div class="field"><label>Strength</label><select id="esh"><option>weak</option><option selected>medium</option><option>strong</option></select></div><div class="field"><label>Source ID</label><input id="esi"></div></div><button class="btn primary" id="sev">Save evidence</button></div></div>`);$('#sev').onclick=()=>{const r=ensureDiscovery();r.evidence.push({id:'E-'+Date.now(),level:$('#elv').value,sourceType:$('#est').value,content:$('#edc').value.trim(),quote:$('#eqt').value.trim(),participantId:$('#ep').value.trim(),segment:$('#esg').value.trim(),stance:$('#esn').value,strength:$('#esh').value,sourceId:$('#esi').value.trim(),date:new Date().toISOString().slice(0,10)});save();persistDiscoveryCanonical();track('discovery_evidence_added');closeModal();render()}}
function openDiscoveryInterview(){openModal(`<div class="pad"><h2>Research session</h2><div class="form"><div class="grid g2"><div class="field"><label>Title</label><input id="rit"></div><div class="field"><label>Participant / segment</label><input id="ria"></div></div><div class="field"><label>Research question asked</label><textarea id="riq"></textarea></div><div class="field"><label>Raw notes</label><textarea id="rin"></textarea></div><button class="btn primary" id="ris">Save session</button></div></div>`);$('#ris').onclick=()=>{const r=ensureDiscovery();r.interviews.push({id:'I-'+Date.now(),title:$('#rit').value.trim(),audience:$('#ria').value.trim(),question:$('#riq').value.trim(),notes:$('#rin').value.trim(),date:new Date().toISOString().slice(0,10)});save();persistDiscoveryCanonical();track('discovery_research_session_added');closeModal();render()}}
function openDiscoveryFinding(){openModal(`<div class="pad"><h2>Research finding</h2><div class="banner">Label the inference level; link it to evidence later instead of treating the finding as raw fact.</div><div class="form"><div class="field"><label>Finding</label><textarea id="ft"></textarea></div><div class="grid g3"><div class="field"><label>Level</label><select id="flv"><option>OBSERVATION</option><option>INTERPRETATION</option><option>OPPORTUNITY</option><option>HYPOTHESIS</option></select></div><div class="field"><label>Source</label><input id="fs"></div><div class="field"><label>Confidence</label><select id="fc"><option>high</option><option selected>medium</option><option>low</option></select></div></div><button class="btn primary" id="fsv">Save finding</button></div></div>`);$('#fsv').onclick=()=>{const r=ensureDiscovery();r.findings.push({id:'F-'+Date.now(),text:$('#ft').value.trim(),level:$('#flv').value,source:$('#fs').value.trim()||'Synthesis',confidence:$('#fc').value});save();persistDiscoveryCanonical();track('discovery_finding_added');closeModal();render()}}

function renderEvidence(){const es=state.decisions.flatMap(d=>(d.evidence||[]).map(e=>({...e,decision:d.title})));return top('Stage 6','Evidence library','Every important claim should be traceable to a source or explicitly marked as an assumption.',`<button class="btn primary" id="goNew">+ Add to decision</button>`)+`<div class="banner warn"><strong>Trust rule:</strong> ThinkForge never treats an AI-generated claim as evidence. Evidence needs a source, date, or explicit user attribution.</div><div class="card pad"><table class="table"><thead><tr><th>Source</th><th>Type</th><th>Claim</th><th>Decision</th><th>Stance</th><th>Strength</th></tr></thead><tbody>${es.map(e=>`<tr><td><strong>${esc(e.source)}</strong><div class="note">${esc(e.date)}</div></td><td>${esc(e.type)}</td><td>${esc(e.content)}</td><td>${esc(e.decision)}</td><td>${esc(e.stance)}</td><td>${esc(e.strength)}</td></tr>`).join('')||'<tr><td colspan="6">No evidence yet.</td></tr>'}</tbody></table></div>`}
function bindEvidence(){document.querySelector('#goNew')?.addEventListener('click',()=>{view='decisions';tab='evidence';render()})}

function renderExperiments(){const ds=state.decisions.filter(d=>d.experiment?.hypothesis);return top('Stage 9–10','Experiments & outcomes','Turn the biggest uncertainty into a reversible test, then compare prediction with reality.',`<button class="btn primary" id="goExp">Open decision</button>`)+`<div class="grid g2">${ds.map(d=>`<div class="card pad"><div class="item-head"><div><strong>${esc(d.title)}</strong><div class="note">${esc(d.experiment.primary||'No primary metric')}</div></div><span class="pill ${d.outcome?.actual!==null?'good':'warn'}">${d.outcome?.actual!==null?'Outcome recorded':'Planned'}</span></div><div class="section grid g3"><div class="mini"><div class="note">Prediction</div><strong>${esc(d.prediction?.predicted??'—')}</strong></div><div class="mini"><div class="note">Actual</div><strong>${esc(d.outcome?.actual??'—')}</strong></div><div class="mini"><div class="note">Result</div><strong>${esc(d.outcome?.result||'pending')}</strong></div></div><div class="note">${esc(d.learning||'No learning recorded yet.')}</div></div>`).join('')}</div>`}
function bindExperiments(){document.querySelector('#goExp')?.addEventListener('click',()=>{view='decisions';tab='experiment';render()})}

function renderEvaluation(){const results=state.evals;const avg=results.length?Math.round(results.reduce((s,x)=>s+x.overall,0)/results.length):null;return top('Research Lab','Human ground truth + AI evaluation','Run the controlled study, inspect reliability, and keep empirical claims tied to frozen evidence.',`<button class="btn primary" id="runEval">Run benchmark</button><button class="btn" id="studyConfig">Study protocol</button>`)+`<div class="grid g4"><div class="card pad kpi"><div class="label">Benchmark</div><div class="value">300</div><div class="muted">60 dev · 60 validation · 180 locked</div></div><div class="card pad kpi"><div class="label">Pilot</div><div class="value">30</div><div class="muted">Training + qualification gate</div></div><div class="card pad kpi"><div class="label">Hidden duplicates</div><div class="value">5%</div><div class="muted">Intra-rater consistency</div></div><div class="card pad kpi"><div class="label">Latest AI score</div><div class="value">${avg===null?'—':avg+'%'}</div><div class="muted">Automated benchmark only</div></div></div><div class="section grid g2"><div class="card pad"><div class="section-head"><h2>Human study gate</h2><span class="pill warn">No fabricated gold</span></div><div class="list"><div class="item"><strong>1. Training → 2. Pilot → 3. Qualification</strong><div class="note">Main-study annotation unlocks only after certification.</div></div><div class="item"><strong>4. Frozen candidates</strong><div class="note">Model, prompt, retriever and output checksum are fixed before annotation.</div></div><div class="item"><strong>5. Independent annotation</strong><div class="note">Two raters; disagreements route to expert adjudication.</div></div></div></div><div class="card pad"><div class="section-head"><h2>Quality signals</h2><span class="pill">research controls</span></div><div class="grid g2"><div class="mini"><strong>Reliability</strong><div class="note">Exact agreement · weighted κ · hidden-duplicate consistency</div></div><div class="mini"><strong>Grounding</strong><div class="note">Supported · partial · unsupported · contradicted · unverifiable</div></div><div class="mini"><strong>Comparative</strong><div class="note">Blind pairwise A/B evaluation with randomized position</div></div><div class="mini"><strong>Decision impact</strong><div class="note">Human-only vs Human + ThinkForge</div></div></div></div></div><div class="section card pad"><div class="section-head"><h2>Automated evaluation runs</h2><span class="pill">${results.length}</span></div>${results.slice(-5).reverse().map(r=>`<div class="item"><div class="item-head"><strong>${esc(r.datasetVersion||'benchmark')}</strong><span class="pill good">${r.overall}%</span></div><div class="note">${esc(r.ranAt||'')}</div></div>`).join('')||'<div class="empty">No benchmark run recorded yet.</div>'}</div>`}
async function bindEval(){document.querySelector('#runEval')?.addEventListener('click',(e)=>withBusy(e.currentTarget,async()=>{try{const r=await fetch('/api/evaluate',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({mode:'benchmark'})});const j=await r.json();if(!r.ok)throw new Error(j.error||'Evaluation failed');state.evals.push(j);save();track('ai_benchmark_run',{overall:j.overall});toast(`Benchmark ${j.overall}%`);render()}catch(e){toast(e.message)}}));document.querySelector('#studyConfig')?.addEventListener('click',(e)=>withBusy(e.currentTarget,async()=>{try{const r=await apiPost('/api/study',{action:'config',studyId:'HG-001'});const j=await r.json();if(!r.ok)throw new Error(j.error||'Study config failed');openModal(`<div class="pad"><div class="section-head"><h2>HG-001 — Human Ground Truth</h2><button class="btn ghost" id="mc">Close</button></div><div class="grid g2"><div class="item"><strong>Dataset</strong><div class="note">${esc(j.study.datasetVersion)}</div></div><div class="item"><strong>Rubric</strong><div class="note">${esc(j.study.rubricVersion)}</div></div><div class="item"><strong>Pilot</strong><div class="note">${j.study.pilotCases} cases</div></div><div class="item"><strong>Reliability</strong><div class="note">${esc(j.study.primaryReliability)}</div></div></div><div class="banner warn" style="margin-top:14px"><strong>Evidence rule:</strong> human gold is created only from independent annotations and adjudication. Synthetic fixtures never unlock research claims.</div></div>`);$('#mc').onclick=closeModal}catch(e){toast(e.message)}}))}

function renderAnalytics(){const ev=[...state.events];const counts={};ev.forEach(e=>counts[e.name]=(counts[e.name]||0)+1);const funnel=['decision_created','assumption_added','evidence_added','ai_action','experiment_created','outcome_recorded'];return top('Stage 12','Analytics','Track the product funnel and AI behavior from first click to outcome.',`<button class="btn" id="clearEvents">Clear local telemetry</button>`)+`<div class="grid g4">${funnel.map(f=>`<div class="card pad kpi"><div class="label">${f.replaceAll('_',' ')}</div><div class="value">${counts[f]||0}</div></div>`).join('')}</div><div class="section grid g2"><div class="card pad"><div class="section-head"><h2>Workflow funnel</h2><span class="pill">local telemetry</span></div>${funnel.map((f,i)=>`<div style="margin:10px 0"><div class="split"><span>${i+1}. ${f.replaceAll('_',' ')}</span><strong>${counts[f]||0}</strong></div><div class="bar"><span style="width:${Math.min(100,((counts[f]||0)/Math.max(1,counts[funnel[0]]||1))*100)}%"></span></div></div>`).join('')}</div><div class="card pad"><div class="section-head"><h2>Event log</h2><span class="pill">${ev.length}</span></div><div class="list">${ev.slice(-12).reverse().map(e=>`<div class="item"><div class="item-head"><strong>${esc(e.name)}</strong><span class="note">${esc(new Date(e.ts).toLocaleTimeString())}</span></div><div class="note">${esc(JSON.stringify(e.props||{}))}</div></div>`).join('')||'<div class="empty">No events yet.</div>'}</div></div></div>`}
function bindAnalytics(){document.querySelector('#clearEvents')?.addEventListener('click',()=>{state.events=[];save();render()})}

function offlineAgent(goal,approved){const runId=`offline-${Date.now()}`,plan={agentVersion:'offline-demo-v1',goal,steps:[{id:'plan',tool:'research_plan',risk:'none'},{id:'collect',tool:'deep_web_research',risk:'external_paid_read'},{id:'synthesize',tool:'evidence_synthesis',risk:'none'},{id:'review',tool:'human_approval',risk:'human_required'}],limitations:['Deterministic demo trace; no provider was contacted.','Use real research before treating a recommendation as evidence.']},trace=[{at:new Date().toISOString(),type:'RUN_STARTED',state:'PLANNED'},{at:new Date().toISOString(),type:'PLAN_CREATED',mode:'deterministic-demo'}];if(!approved){trace.push({at:new Date().toISOString(),type:'AWAITING_APPROVAL',blockedTool:'deep_web_research'});return{runId,status:'AWAITING_APPROVAL',plan,trace,metrics:{toolCalls:0,externalToolCalls:0,costUsd:0}}}trace.push({at:new Date().toISOString(),type:'POLICY_EVALUATED',tool:'deep_web_research',allowed:true,mode:'simulated'},{at:new Date().toISOString(),type:'TOOL_COMPLETED',tool:'deep_web_research',retainedSources:0,mode:'simulated_no_network'},{at:new Date().toISOString(),type:'SYNTHESIS_COMPLETED',mode:'deterministic-demo'},{at:new Date().toISOString(),type:'HUMAN_REVIEW_REQUIRED'});return{runId,status:'NEEDS_HUMAN_REVIEW',plan,trace,metrics:{toolCalls:2,externalToolCalls:0,costUsd:0}}}
function renderAgent(){const runs=state.agentRuns||[],offline=state.settings.offlineDemo;return top('Human-supervised AI','Research agent','Plan evidence collection, approve external research, then inspect an auditable trace. The agent cannot approve or execute product decisions.',`<button class="btn primary" id="agentPlan">Create plan</button>`)+`<div class="grid g2"><div class="card pad"><div class="section-head"><h2>Run a bounded investigation</h2><span class="pill warn">Approval required</span></div><div class="field"><label>Research goal</label><textarea id="agentGoal" placeholder="Why do new SMB users abandon onboarding before activation?"></textarea></div><div class="field"><label>Organization ID ${offline?'optional in free demo':'required for cloud run'}</label><input id="agentOrg" placeholder="${offline?'Leave blank to run locally':'Required for authenticated API runs'}"></div><div class="actions"><button class="btn" id="agentPlan">Plan only</button><button class="btn primary" id="agentRun">Approve & run</button></div><div class="banner warn" style="margin-top:12px">${offline?'Free demo mode creates a deterministic simulated trace with no network calls or costs.':'External research can use paid providers. Plan first; only the explicit run action approves collection.'}</div></div><div class="card pad"><div class="section-head"><h2>Operational scorecard</h2><span class="pill">no fabricated metrics</span></div><div class="list"><div class="item"><strong>Agent runs recorded</strong><div class="note">${runs.length} local traces</div></div><div class="item"><strong>Required proof</strong><div class="note">Run reliability, P95 latency, provider cost, and evaluation grounding appear only after staging traffic.</div></div><div class="item"><strong>Safety boundary</strong><div class="note">The agent pauses before external research and always routes recommendations to a human reviewer.</div></div></div></div></div><div class="section card pad"><div class="section-head"><h2>Recent agent traces</h2><span class="pill">${runs.length}</span></div>${runs.slice(-5).reverse().map(r=>{const runStatus=r.status||r.state||'PLANNED';const trace=r.trace||r.steps||[];return `<div class="item"><div class="item-head"><strong>${esc(r.plan?.goal||r.goal||'Research run')}</strong><span class="pill ${runStatus==='FAILED'?'bad':runStatus==='NEEDS_HUMAN_REVIEW'?'warn':'good'}">${esc(runStatus)}</span></div><div class="note">${esc(trace.map(x=>x.type||x.event_type).join(' → '))}</div></div>`}).join('')||'<div class="empty">Create a plan to produce the first auditable trace.</div>'}</div>`}
async function bindAgent(){const execute=async approved=>{const goal=$('#agentGoal')?.value.trim(),organizationId=$('#agentOrg')?.value.trim();if(!goal)return toast('Enter a research goal');if(state.settings.offlineDemo&&!organizationId){const result=offlineAgent(goal,approved);(state.agentRuns||(state.agentRuns=[])).push(result);save();track(approved?'offline_agent_run_completed':'offline_agent_plan_created',{status:result.status,mode:'deterministic-demo'});toast(approved?`Offline agent ${result.status}`:'Offline agent plan created');render();return}if(!organizationId)return toast('Organization ID is required for a cloud agent run');try{const r=await apiPost('/api/agent',{action:approved?'run':'plan',organizationId,approved,input:{goal,researchQuestion:goal,desiredOutcome:'Identify the highest-value evidence-backed next action',decisionImpact:'high'}}),j=await r.json();if(!r.ok)throw new Error(j.error||'Agent request failed');const result=j.result||j;(state.agentRuns||(state.agentRuns=[])).push(result);save();track(approved?'agent_run_completed':'agent_plan_created',{status:result.status||'PLANNED'});toast(approved?`Agent ${result.status}`:'Agent plan created');render()}catch(e){toast(e.message)}};document.querySelectorAll('#agentPlan').forEach(b=>b.addEventListener('click',()=>execute(false)));$('#agentRun')?.addEventListener('click',()=>execute(true))}

function renderRag(){return top('Stage 13','Evidence RAG','Upload research, retrieve relevant chunks, and attach grounded evidence to a decision.',`<label class="btn primary">Upload files<input id="ragFiles" type="file" multiple accept=".txt,.md,.csv,.json,.log,.pdf" hidden></label>`)+`<div class="grid g2"><div class="card pad"><div class="section-head"><h2>Indexed documents</h2><span class="pill">${state.rag.documents.length}</span></div><div class="list">${state.rag.documents.map(d=>`<div class="item"><div class="item-head"><strong>${esc(d.name)}</strong><span class="pill">${d.chunks} chunks</span></div><div class="note">${esc(d.type)} · ${esc(d.date)}</div></div>`).join('')||'<div class="empty">Upload interview notes, research or text documents.</div>'}</div></div><div class="card pad"><div class="section-head"><h2>Retrieve</h2><span class="pill">Citation-ready</span></div><div class="field"><label>Query</label><textarea id="ragQuery" placeholder="Which evidence supports users wanting safer retry guidance?"></textarea></div><div class="actions" style="margin-top:10px"><button class="btn primary" id="ragSearch">Search evidence</button></div><div id="ragResults" class="list" style="margin-top:12px"></div></div></div>`}
async function bindRag(){document.querySelector('#ragFiles')?.addEventListener('change',async e=>{for(const f of [...e.target.files])await indexFile(f);save();track('rag_file_indexed',{count:e.target.files.length});render()});document.querySelector('#ragSearch')?.addEventListener('click',(e)=>withBusy(e.currentTarget,async()=>{const q=$('#ragQuery').value;let hits=[];if(supa&&state.user){try{const sess=(await supa.auth.getSession()).data.session;if(sess?.access_token){const rr=await fetch('/api/rag',{method:'POST',headers:{'Content-Type':'application/json','Authorization':'Bearer '+sess.access_token},body:JSON.stringify({action:'search',payload:{query:q}})});const jj=await rr.json();if(rr.ok)hits=jj.hits||[];}}catch(e){console.warn('Cloud RAG search failed',e)}}if(!hits.length)hits=state.rag.chunks.map(c=>({...c,score:score(q,c.text)})).filter(x=>x.score>0).sort((a,b)=>b.score-a.score).slice(0,8);const box=$('#ragResults');box.innerHTML=hits.length?hits.map(h=>`<div class="item"><div class="item-head"><strong>${esc(h.docName)}</strong><span class="pill">${h.score} matches</span></div><div class="note">${esc(h.meta)}</div><div style="margin-top:7px">${esc(h.text)}</div><button class="btn ghost" style="margin-top:8px" data-attach-hit="${h.id}">Attach to selected decision</button></div>`).join(''):'<div class="empty">No matching evidence.</div>';document.querySelectorAll('[data-attach-hit]').forEach(b=>b.onclick=()=>{const d=current(),h=state.rag.chunks.find(x=>x.id===b.dataset.attachHit);if(!d||!h)return;d.evidence.push({id:'e'+Date.now(),type:'RAG',source:h.docName,content:h.text,stance:'neutral',strength:'medium',date:new Date().toISOString().slice(0,10),linked:[],url:''});commit('Evidence attached');track('rag_evidence_attached',{decision_id:d.id})})}));}
function score(q,t){const terms=(q||'').toLowerCase().split(/\s+/).filter(x=>x.length>2);const low=(t||'').toLowerCase();return terms.reduce((s,x)=>s+(low.includes(x)?1:0),0)}
async function indexFile(f){const id='doc'+Date.now()+Math.random().toString(16).slice(2);let text='';if(/\.(txt|md|csv|json|log)$/i.test(f.name)||f.type.startsWith('text/'))text=await f.text();else if(/\.pdf$/i.test(f.name)){text='PDF uploaded. In production, use the server extraction pipeline; for this static MVP, convert PDF text to .txt or use a PDF parser script.'}if(!text.trim()){toast('No extractable text');return}const chunks=[];for(let i=0;i<text.length;i+=1040)chunks.push(text.slice(i,i+1040).replace(/\s+/g,' ').trim());state.rag.documents.push({id,name:f.name,type:f.type||'file',date:new Date().toISOString().slice(0,10),chunks:chunks.length});chunks.forEach((t,i)=>state.rag.chunks.push({id:id+'c'+i,docId:id,docName:f.name,text:t,meta:`chunk ${i+1}/${chunks.length}`})); if(supa&&state.user){try{const sess=(await supa.auth.getSession()).data.session;if(sess?.access_token){await fetch('/api/rag',{method:'POST',headers:{'Content-Type':'application/json','Authorization':'Bearer '+sess.access_token},body:JSON.stringify({action:'upsert',payload:{name:f.name,mimeType:f.type,chunks}})});}}catch(e){console.warn('Cloud RAG sync failed',e)}}}

function renderExecution(){const d=current();return top('Stage 14','PRD + Jira execution','Carry an evidence-backed decision into requirements and implementation work.',`<button class="btn" id="genPrd">Generate PRD</button><button class="btn primary" id="pushJira">Create Jira work</button>`)+`<div class="grid g2"><div class="card pad"><div class="section-head"><h2>PRD</h2><span class="pill">Traceable</span></div>${d.prd?`<pre style="white-space:pre-wrap;background:#f8f9fb;padding:12px;border-radius:10px;max-height:600px;overflow:auto">${esc(d.prd)}</pre>`:'<div class="empty">Generate a PRD from this decision. The output should use only information already in the decision record.</div>'}</div><div class="card pad"><div class="section-head"><h2>Jira</h2><span class="pill">Server-side credentials</span></div><div class="banner warn">Jira credentials are never stored in this browser build. Configure <code>JIRA_BASE_URL</code>, <code>JIRA_EMAIL</code>, <code>JIRA_API_TOKEN</code>, and <code>JIRA_PROJECT_KEY</code> in Vercel.</div><div class="list">${(d.jira||[]).map(x=>`<div class="item"><div class="item-head"><strong>${esc(x.summary)}</strong><span class="pill">${esc(x.key||'created')}</span></div></div>`).join('')||'<div class="empty">No Jira issues created from this decision yet.</div>'}</div></div></div>`}
async function bindExecution(){document.querySelector('#genPrd')?.addEventListener('click',(e)=>withBusy(e.currentTarget,async()=>{try{const r=await apiPost('/api/ai',{action:'prd',decision:current()});const j=await r.json();if(!r.ok)throw new Error(j.error||'AI not configured');current().prd=JSON.stringify(j.data,null,2);save();track('prd_generated',{decision_id:current().id});toast('PRD generated');render()}catch(e){toast(e.message)}}));document.querySelector('#pushJira')?.addEventListener('click',(e)=>{if(!confirm('Create an Epic and linked Jira tasks from this decision? This performs external writes.'))return;return withBusy(e.currentTarget,async()=>{try{const r=await fetch('/api/jira',{method:'POST',headers:{...(await authHeaders()),'Idempotency-Key':'jira-'+current().id+'-'+Date.now()},body:JSON.stringify({decision:current(),confirm:true})});const j=await r.json();if(!r.ok)throw new Error(j.error||'Jira not configured');current().jira=j.issues;save();track('jira_work_created',{decision_id:current().id,count:j.issues.length});toast('Jira work created');render()}catch(e){toast(e.message)}})})}

function renderInsights(){const ds=state.decisions;const completed=ds.filter(d=>d.outcome?.actual!==null&&Number.isFinite(Number(d.prediction?.predicted)));const gaps=completed.map(d=>Number(d.prediction.predicted)-Number(d.outcome.actual));const avgGap=gaps.length?(gaps.reduce((a,b)=>a+b,0)/gaps.length):null;const blind=[];ds.forEach(d=>(d.assumptions||[]).filter(a=>a.status!=='validated'&&a.impact>=4).forEach(a=>blind.push({t:a.text,p:a.impact*a.uncertainty,d:d.title})));blind.sort((a,b)=>b.p-a.p);return top('Stage 15','Advanced insights','Learn from your historical reasoning instead of starting from zero each time.',`<button class="btn" id="refreshInsights">Refresh</button>`)+`<div class="grid g3"><div class="card pad kpi"><div class="label">Completed predictions</div><div class="value">${completed.length}</div></div><div class="card pad kpi"><div class="label">Average prediction gap</div><div class="value">${avgGap===null?'—':avgGap.toFixed(1)}</div><div class="muted">predicted − actual</div></div><div class="card pad kpi"><div class="label">High-risk open assumptions</div><div class="value">${blind.length}</div></div></div><div class="section grid g2"><div class="card pad"><div class="section-head"><h2>Calibration</h2><span class="pill ${avgGap!==null&&Math.abs(avgGap)<=5?'good':'warn'}">${avgGap===null?'Need more data':Math.abs(avgGap)<=5?'Reasonably calibrated':'Review optimism'}</span></div>${completed.map(d=>`<div class="item"><div class="item-head"><strong>${esc(d.title)}</strong><span class="pill">gap ${(Number(d.prediction.predicted)-Number(d.outcome.actual)).toFixed(1)}</span></div><div class="note">Prediction ${esc(d.prediction.predicted)} · Actual ${esc(d.outcome.actual)}</div></div>`).join('')||'<div class="empty">Record experiment outcomes to unlock calibration insights.</div>'}</div><div class="card pad"><div class="section-head"><h2>Reasoning blind spots</h2><span class="pill warn">prioritized</span></div>${blind.slice(0,8).map(x=>`<div class="item"><strong>${esc(x.t)}</strong><div class="note">Priority ${x.p}/25 · ${esc(x.d)}</div></div>`).join('')||'<div class="empty">No high-impact unresolved assumptions.</div>'}</div></div>`}
function bindInsights(){}

async function showSettings(){openModal(`<div class="pad"><div class="section-head"><h2>Settings</h2><button class="btn ghost" id="mc">Close</button></div><div class="banner warn"><strong>Deployment safety:</strong> AI and Jira secrets belong in server environment variables. Do not store provider secrets in the browser.</div><div class="form"><label class="item"><input id="od" type="checkbox" ${state.settings.offlineDemo?'checked':''}> <strong>Free Offline Demo Mode</strong><div class="note">Uses deterministic local examples when AI/cloud services are unavailable. It never represents them as real research or model output.</div></label><div class="field"><label>Django API base URL</label><input id="da" value="${esc(state.settings.djangoApiBase||'')}" placeholder="http://localhost:8000 (leave blank for same origin)"></div><div class="field"><label>Supabase URL</label><input id="su" value="${esc(state.settings.supabaseUrl)}" placeholder="https://xxxxx.supabase.co"></div><div class="field"><label>Supabase anon key</label><input id="sk" value="${esc(state.settings.supabaseAnonKey)}"></div><div class="field"><label>PostHog project key</label><input id="pk" value="${esc(state.settings.posthogKey)}" placeholder="phc_..."></div><div class="field"><label>PostHog host</label><input id="ph" value="${esc(state.settings.posthogHost)}"></div><button class="btn primary" id="ms">Save settings</button></div></div>`);$('#mc').onclick=closeModal;$('#ms').onclick=()=>{state.settings.offlineDemo=$('#od').checked;state.settings.djangoApiBase=$('#da').value.trim().replace(/\/$/,'');state.settings.supabaseUrl=$('#su').value.trim();state.settings.supabaseAnonKey=$('#sk').value.trim();state.settings.posthogKey=$('#pk').value.trim();state.settings.posthogHost=$('#ph').value.trim()||'https://us.i.posthog.com';save();closeModal();initIntegrations();toast('Settings saved');render()}}
async function showAuth(){openModal(`<div class="pad"><div class="section-head"><h2>ThinkForge account</h2><button class="btn ghost" id="mc">Close</button></div><div class="banner">Cloud persistence is optional. In local mode, your data stays in this browser.</div><div class="form"><div class="field"><label>Email</label><input id="ae" type="email"></div><div class="field"><label>Password</label><input id="ap" type="password"></div><div class="actions"><button class="btn" id="login">Sign in</button><button class="btn primary" id="signup">Create account</button><button class="btn ghost" id="logout">Sign out</button></div><div class="note" id="authStatus"></div></div></div>`);$('#mc').onclick=closeModal;$('#login').onclick=()=>auth('login');$('#signup').onclick=()=>auth('signup');$('#logout').onclick=async()=>{await supa?.auth.signOut();toast('Signed out');closeModal()}}
async function auth(mode){if(!supa){$('#authStatus').textContent='Configure Supabase URL + anon key in Settings first.';return}const email=$('#ae').value,password=$('#ap').value;const r=mode==='login'?await supa.auth.signInWithPassword({email,password}):await supa.auth.signUp({email,password});$('#authStatus').textContent=r.error?r.error.message:'Check your email if confirmation is enabled.';if(!r.error){await loadCloud();closeModal();render()}}
async function initIntegrations(){try{if(!state.settings.supabaseUrl||!state.settings.supabaseAnonKey||!state.settings.posthogKey){const cfg=await fetch('/api/config').then(r=>r.json());state.settings.supabaseUrl=state.settings.supabaseUrl||cfg.supabaseUrl;state.settings.supabaseAnonKey=state.settings.supabaseAnonKey||cfg.supabaseAnonKey;state.settings.posthogKey=state.settings.posthogKey||cfg.posthogKey;state.settings.posthogHost=state.settings.posthogHost||cfg.posthogHost;localSave()}}catch{}if(state.settings.supabaseUrl&&state.settings.supabaseAnonKey){try{const mod=await import('https://cdn.jsdelivr.net/npm/@supabase/supabase-js@2/+esm');supa=mod.createClient(state.settings.supabaseUrl,state.settings.supabaseAnonKey);const sess=(await supa.auth.getSession()).data.session;if(sess){state.user={id:sess.user.id,email:sess.user.email};await loadCloud();}}catch(e){console.warn(e)}}}
async function loadCloud(){if(!supa||!state.user)return;try{const {data,error}=await supa.from('thinkforge_workspaces').select('state').eq('user_id',state.user.id).maybeSingle();if(!error&&data?.state){const remote=data.state;state={...state,...remote,user:state.user,settings:{...state.settings,...remote.settings}};save()}}catch(e){console.warn(e)}}
async function syncCloud(){if(!supa||!state.user)return;try{const sess=(await supa.auth.getSession()).data.session;if(!sess?.access_token)return;const remote=await apiPost('/api/workspace',{state,event:null,expectedVersion:state.cloudVersion||null});if(remote.ok){const j=await remote.json();state.cloudVersion=j.version||state.cloudVersion||1;localSave()}}catch(e){console.warn('Cloud sync failed',e)}}
save=()=>{localSave();syncCloud()};


// Stage 3 UX system: contextual quick actions + keyboard-first navigation.
let commandPalette,shortcutsBound=false;
function openCommands(){commandPalette?.open()}
function closeCommands(){$('#commandWrap')?.classList.remove('open');announce('Command palette closed')}
function renderCommands(filter=''){commandPalette?.render(filter)}
const SHORTCUTS=[['⌘ / Ctrl + K','Open quick actions'],['N','New decision (when not typing)'],['?','Show this shortcut list'],['Esc','Close dialog or command palette'],['Tab / Shift+Tab','Move focus inside an open dialog']];
function showShortcuts(){track('shortcuts_opened',{});openModal(`<div class="pad"><div class="section-head"><div><div class="section-kicker">Move faster</div><h2 id="modalTitle" style="margin:4px 0 0">Keyboard shortcuts</h2></div><button class="btn ghost" id="mc">Close</button></div><div class="shortcuts-grid">${SHORTCUTS.map(([k,l])=>`<div class="item"><span>${esc(l)}</span><span class="key-hint" style="opacity:1">${esc(k)}</span></div>`).join('')}</div></div>`);$('#mc').onclick=closeModal}
function bindCommands(){
  commandPalette=createCommandPalette({root:$('#commandWrap'),input:$('#commandInput'),list:$('#commandList'),esc,close:closeCommands,run:(c)=>{
    track('command_used',{command_id:c.id});
    if(c.id==='new')return newDecision();
    if(c.id==='shortcuts')return showShortcuts();
    const routes={decisions:'decisions',research:'discovery',evidence:'evidence',experiments:'experiments',learn:'insights',evaluation:'evaluation',analytics:'analytics',rag:'rag',execution:'execution'};
    if(routes[c.id]){view=routes[c.id];if(view==='decisions')tab='overview';render()}
  }});
  commandPalette.bind();
  $('#commandBtn')?.addEventListener('click',openCommands);
  $('#commandClose')?.addEventListener('click',closeCommands);
  $('#commandWrap')?.addEventListener('click',e=>{if(e.target.id==='commandWrap')closeCommands()});
  if(!shortcutsBound){shortcutsBound=true;installGlobalShortcuts({openCommands,closeCommands:()=>{closeCommands();closeModal()},openShortcuts:showShortcuts,newDecision})}
}

function updateOfflineBanner(){const b=$('#offlineBanner');if(!b)return;const offline=!navigator.onLine;b.hidden=!offline;if(offline)announce('You are offline. Changes are saved locally.')}
window.addEventListener('online',()=>{updateOfflineBanner();toast('Back online — syncing');syncCloud()});
window.addEventListener('offline',updateOfflineBanner);

// Stage buttons that need view-level bindings

function decorateDecisionUX(){if(view!=='decisions')return;const root=$('#root'),d=current();if(!root||!d)return;const anchor=root.querySelector('.decision-context');if(anchor&&!root.querySelector('.lineage-card'))anchor.insertAdjacentHTML('afterend',renderDecisionLineage(d));const host=root.querySelector('.lineage-card');if(host&&!root.querySelector('.ost-enhanced'))host.insertAdjacentHTML('afterend',renderOpportunitySolutionTree(d));}
function productRisks(d){const r=stage4Readiness(d);return r.blockers.slice(0,3).map(x=>x.label).concat((d.assumptions||[]).filter(a=>a.status!=='validated').sort((a,b)=>(b.impact*b.uncertainty)-(a.impact*a.uncertainty)).slice(0,3-r.blockers.length).map(a=>`Validate: ${a.text}`)).slice(0,3)}
function renderActivation(){return `<section class="activation-card" aria-label="Product decision workflow"><div class="section-kicker">The product-manager workflow</div><h2>Turn product uncertainty into an evidence-backed decision.</h2><div class="sub">Start with a decision. ThinkForge will keep the evidence, risks, recommendation, and stakeholder brief in one place.</div><div class="activation-steps"><div class="activation-step"><strong>1. Decision</strong><span>State the choice and customer problem.</span></div><div class="activation-step"><strong>2. Evidence</strong><span>Attach research, data, and assumptions.</span></div><div class="activation-step"><strong>3. Risks</strong><span>Focus on gaps and contradictions.</span></div><div class="activation-step"><strong>4. Next action</strong><span>Validate, build, defer, or reject.</span></div><div class="activation-step"><strong>5. Share</strong><span>Send a decision brief for review.</span></div></div><div class="actions" style="margin-top:16px"><button class="btn primary" id="productStartDecision">Start a decision</button><button class="btn" id="productOpenBrief">Open decision brief</button></div></section>`}
function renderProductPanel(d){const r=stage4Readiness(d),risks=productRisks(d),reviewers=d.reviewers||[],comments=d.comments||[];return `<section class="product-panel" aria-label="Decision health and collaboration"><div class="product-panel-grid"><div><div class="section-kicker">Decision health</div><div class="item-head"><strong>${Math.round(r.confidence*100)}% confidence</strong><span class="pill ${r.readyForReview?'good':'warn'}">${r.readyForReview?'Review-ready':'Needs evidence'}</span></div><div class="risk-list">${(risks.length?risks:['No high-priority risk detected yet.']).map(x=>`<div class="risk-item"><span class="risk-mark">!</span><span>${esc(x)}</span></div>`).join('')}</div><div class="actions" style="margin-top:12px"><button class="btn" id="productEvidence">Add evidence</button><button class="btn" id="productExperiment">Suggested experiment</button></div></div><div><div class="section-kicker">Owner and review</div><div class="product-meta"><label>Owner<input id="productOwner" value="${esc(d.owner||'')}" placeholder="Decision owner"></label><label>Review due<input id="productDue" type="date" value="${esc(d.dueDate||'')}"></label></div><div class="collab-row"><button class="btn" id="productSaveMeta">Save details</button><button class="btn" id="productRequestReview">Request review</button><button class="btn" id="productComment">Add comment</button></div><div class="collab-note">${reviewers.length?`Review requested from ${esc(reviewers.join(', '))}. `:'No reviewers requested yet. '}${comments.length?`${comments.length} comment${comments.length===1?'':'s'}.`:''}</div></div></div></section>`}
function openReviewRequest(){const d=current();openModal(`<div class="pad"><div class="section-head"><div><div class="section-kicker">Request a decision review</div><h2 id="modalTitle" style="margin:4px 0 0">Bring stakeholders in early</h2></div><button class="btn ghost" id="mc">Close</button></div><div class="field"><label for="reviewerNames">Reviewers</label><input id="reviewerNames" placeholder="e.g. Priya (Design), Alex (Engineering)"></div><div class="field" style="margin-top:12px"><label for="reviewNote">Message</label><textarea id="reviewNote" placeholder="What decision needs feedback, and by when?"></textarea></div><div class="actions" style="margin-top:16px"><button class="btn primary" id="sendReviewRequest">Save review request</button></div></div>`);$('#mc').onclick=closeModal;$('#sendReviewRequest').onclick=()=>{const reviewers=$('#reviewerNames').value.split(',').map(x=>x.trim()).filter(Boolean);if(!reviewers.length){toast('Add at least one reviewer');return}d.reviewers=[...new Set([...(d.reviewers||[]),...reviewers])];d.reviewRequests=[...(d.reviewRequests||[]),{reviewers,note:$('#reviewNote').value.trim(),at:new Date().toISOString(),status:'requested'}];commit('Review request saved');track('decision_review_requested',{decision_id:d.id,reviewer_count:reviewers.length});closeModal();render()}}
function openComment(){const d=current();openModal(`<div class="pad"><div class="section-head"><div><div class="section-kicker">Decision comment</div><h2 id="modalTitle" style="margin:4px 0 0">Capture stakeholder feedback</h2></div><button class="btn ghost" id="mc">Close</button></div><div class="field"><label for="commentAuthor">Name</label><input id="commentAuthor" placeholder="Your name"></div><div class="field" style="margin-top:12px"><label for="commentText">Comment</label><textarea id="commentText" placeholder="What should change, be validated, or be considered?"></textarea></div><div class="actions" style="margin-top:16px"><button class="btn primary" id="saveComment">Add comment</button></div></div>`);$('#mc').onclick=closeModal;$('#saveComment').onclick=()=>{const text=$('#commentText').value.trim();if(!text){toast('Write a comment before saving');return}d.comments=[...(d.comments||[]),{author:$('#commentAuthor').value.trim()||'Teammate',text,at:new Date().toISOString()}];commit('Comment added');track('decision_comment_added',{decision_id:d.id});closeModal();render()}}
function openMonthlyCheckin(){const d=current();openModal(`<div class="pad"><div class="section-head"><div><div class="section-kicker">Outcome check-in</div><h2 id="modalTitle" style="margin:4px 0 0">What happened after this decision?</h2></div><button class="btn ghost" id="mc">Close</button></div><div class="field"><label for="checkinSignal">Metric or signal</label><input id="checkinSignal" value="${esc(d.prediction?.metric||'')}" placeholder="e.g. Activation rate"></div><div class="field" style="margin-top:12px"><label for="checkinLearning">What did the team learn?</label><textarea id="checkinLearning" placeholder="Capture the outcome, unexpected result, or next adjustment."></textarea></div><div class="actions" style="margin-top:16px"><button class="btn primary" id="saveCheckin">Save check-in</button></div></div>`);$('#mc').onclick=closeModal;$('#saveCheckin').onclick=()=>{const learning=$('#checkinLearning').value.trim();if(!learning){toast('Add a short learning to save the check-in');return}d.monthlyCheckins=[...(d.monthlyCheckins||[]),{signal:$('#checkinSignal').value.trim(),learning,at:new Date().toISOString()}];d.learning=d.learning||learning;commit('Outcome check-in saved');track('decision_outcome_checkin',{decision_id:d.id});closeModal();render()}}
function decorateProductExperience(){const root=$('#root');if(!root)return;if(view==='dashboard'){const hero=root.querySelector('.home-hero');if(hero&&!root.querySelector('.activation-card'))hero.insertAdjacentHTML('beforebegin',renderActivation());$('#productStartDecision')?.addEventListener('click',newDecision);$('#productOpenBrief')?.addEventListener('click',openDecisionBrief)}if(view==='decisions'){const context=root.querySelector('.decision-context'),d=current();if(context&&d&&!root.querySelector('.product-panel'))context.insertAdjacentHTML('afterend',renderProductPanel(d));$('#productEvidence')?.addEventListener('click',()=>{tab='evidence';render()});$('#productExperiment')?.addEventListener('click',()=>{tab='experiment';render()});$('#productSaveMeta')?.addEventListener('click',()=>{d.owner=$('#productOwner').value.trim();d.dueDate=$('#productDue').value;commit('Decision owner and review date saved');render()});$('#productRequestReview')?.addEventListener('click',openReviewRequest);$('#productComment')?.addEventListener('click',openComment);if(d&&!d.monthlyCheckins?.length){const panel=root.querySelector('.product-panel');panel?.insertAdjacentHTML('beforeend',`<div class="collab-row"><button class="btn ghost" id="productCheckin">Record monthly outcome check-in</button></div>`);$('#productCheckin')?.addEventListener('click',openMonthlyCheckin)}}}
const oldRender=render; render=function(){oldRender();decorateProductExperience();decorateDecisionUX()}
const oldBind=bind; bind=function(){oldBind();bindEvidence();bindExperiments();bindAnalytics();bindAgent();bindInsights();bindCommands();const briefButton=$('#briefBtn');if(briefButton)briefButton.onclick=openDecisionBrief;const advancedToggle=$('#advancedToggle'),advancedNav=$('#advancedNav');if(advancedToggle&&advancedNav)advancedToggle.onclick=()=>{const expanded=advancedToggle.getAttribute('aria-expanded')==='true';advancedToggle.setAttribute('aria-expanded',String(!expanded));advancedNav.hidden=expanded}}
window.addEventListener('thinkforge:web-vital',e=>{recordUXMetric(state,'web_vital',e.detail);});
webVitals();
initIntegrations();track('app_opened');render();updateOfflineBanner();
